MultiLanguageSpellData['it'][400026] = {name = "[q2]Medaglione del Combattente Cremisi", additional_info = "2 s di lancio\nReagenti:\nIra Risvegliata (2), Inchiostro Sereno (3), Runa Raggelata\nReagenti Facoltativi:\nConsapevolezza Illustre Minore (#92) , Sabbia Assorbente (#249)\nMercante:\nKorganar Forgiardente\nZona:\nValdrakken\nCosto:\n3\n\n[q2]Medaglione del Combattente Cremisi\nSi vincola all'equipaggiamento\nUnico equipaggiabile: Medaglioni del Gladiatore (1)Monile\n+205 [Agilità o Forza o Intelletto][q2]Usa: Dissolve tutti gli effetti di limitazione al movimento e tutti gli effetti di perdita di controllo del personaggio.\n70\n\n[q]Onorificenza del Gladiatore (0/2)\n[q0]Emblema del Gladiatore\nMedaglione del Gladiatore"}
MultiLanguageSpellData['it'][400027] = {name = "[q2]Fregio dell'Alacrità del Combattente Cremisi", additional_info = "2 s di lancio\nReagenti:\nIra Risvegliata (2), Inchiostro Fiammeggiante (3), Runa Raggelata\nReagenti Facoltativi:\nConsapevolezza Illustre Minore (#92) , Sabbia Assorbente (#249)\nMercante:\nKorganar Forgiardente\nZona:\nValdrakken\nCosto:\n3\n\n[q2]Fregio dell'Alacrità del Combattente Cremisi\nSi vincola all'equipaggiamento\nUnico equipaggiabileMonile\n[q2]+ 291 Celerità\n[q2]Equipaggia: Gli incantesimi e le abilità hanno una probabilità di aumentare l'attributo primario di 457 per 20 s.\n70\n\n[q]Onorificenza del Gladiatore (0/2)\n[q0]Emblema del Gladiatore\nMedaglione del Gladiatore"}
MultiLanguageSpellData['it'][400028] = {name = "[q2]Emblema del Combattente Cremisi", additional_info = "2 s di lancio\nReagenti:\nIra Risvegliata (2), Inchiostro Rigoglioso (3), Runa Raggelata\nReagenti Facoltativi:\nConsapevolezza Illustre Minore (#92) , Sabbia Assorbente (#249)\nMercante:\nKorganar Forgiardente\nZona:\nValdrakken\nCosto:\n3\n\n[q2]Emblema del Combattente Cremisi\nSi vincola all'equipaggiamento\nUnico equipaggiabileMonile\n+205 [Agilità o Forza o Intelletto][q2]Usa: Aumenta la salute massima di 26226 per 15 s. (2 Min Recupero)\n70\n\n[q]Onorificenza del Gladiatore (0/2)\n[q0]Emblema del Gladiatore\nMedaglione del Gladiatore"}
