MultiLanguageSpellData['it'][400807] = {name = "[q4]Borsello di Spezie Scintillante", additional_info = "3.5 s di lancio\nReagenti:\nSpezie Scialbe\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Borsello di Spezie Scintillante\nStranezze dell'Artigiano\n[q]\"L'ingrediente che mancava era l'amore! L'aroma è incredibile. Un ottimo assaggio dell'Isola Proibita. Può attivare uno scontro speciale.\""}
MultiLanguageSpellData['it'][400808] = {name = "[q4]Tridente Cerimoniale Antico", additional_info = "3.5 s di lancio\nReagenti:\nTridente Danneggiato\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Tridente Cerimoniale Antico\nStranezze dell'Artigiano\n[q]\"Questo tridente non è fatto con materiali adatti al combattimento, è adatto solo ai rituali. Meglio stare attenti a dove lo si mette sull'Isola Proibita. Può attivare uno scontro speciale.\""}
MultiLanguageSpellData['it'][400809] = {name = "[q4]Segnalibro di Cristallo Luminoso", additional_info = "3.5 s di lancio\nReagenti:\nCristallo Opaco\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Segnalibro di Cristallo Luminoso\nStranezze dell'Artigiano\n[q]\"Questo segnalibro luccicante sta implorando di essere messo in un buon libro, come quelli che si trovano nell'Isola Proibita. Può attivare uno scontro speciale.\""}
MultiLanguageSpellData['it'][400810] = {name = "[q4]Scatola Vocale Gnomesca", additional_info = "3.5 s di lancio\nReagenti:\nScatola Vocale Gnomesca Rotta\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Scatola Vocale Gnomesca\nStranezze dell'Artigiano\n[q]\"Come ha fatto la tecnologia gnomesca a raggiungere l'Isola Proibita? Per usarlo serve una vibrospira. Può attivare uno scontro speciale.\""}
MultiLanguageSpellData['it'][400811] = {name = "[q4]Runa Dissolvente Arcana", additional_info = "3.5 s di lancio\nReagenti:\nRuna Scarabocchiata di Fretta\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Runa Dissolvente Arcana\nStranezze dell'Artigiano\n[q]\"Dopo averne ripulito le linee, è chiaro che questa runa era destinata a dissolvere protezioni, come quelle dell'Isola Proibita. Può attivare uno scontro speciale.\""}
MultiLanguageSpellData['it'][400812] = {name = "[q4]Diapason Cristallino", additional_info = "3.5 s di lancio\nReagenti:\nForchettone Cristallino\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Diapason Cristallino\nStranezze dell'Artigiano\n[q]\"Colpire il cristallo giusto nell'Isola Proibita con questo strumento dovrebbe produrre una nota melodiosa. Può attivare uno scontro speciale.\""}
MultiLanguageSpellData['it'][400813] = {name = "Frizione del Tempo", additional_info = "[q0][Item Effect][q]Imbriglia il calore delle scardinate linee temporali durante l'evento Furia dei Cieli nel Futuro dei Primalisti per rimuovere un accumulo di Congelamento ogni 11 s."}
MultiLanguageSpellData['it'][400814] = {name = "[q4]Cuoio Intatto Rinforzato", additional_info = "3.5 s di lancio\nReagenti:\nPelliccia Intatta\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Cuoio Intatto Rinforzato\nStranezze dell'Artigiano\n[q]\"Queste pezze di cuoio rinforzato vengono spesso usate dai Tuskarr di Morqut per riparare delle pelli danneggiate dell'Isola Proibita. Può attivare uno scontro speciale.\""}
MultiLanguageSpellData['it'][400815] = {name = "[q4]Aquilone di Morqut Tradizionale", additional_info = "3.5 s di lancio\nReagenti:\nAquilone di Morqut Strappato\nMercante:\nCommerciante Hag'arth\nZona:\nIsola Proibita\nCosto:\n10\n\n[q4]Aquilone di Morqut Tradizionale\nStranezze dell'Artigiano\n[q]\"Alcuni dicono che gli aquiloni dei Tuskarr legati ai pali nell'Isola Proibita sappiano volare sulle ali degli spiriti. Può attivare uno scontro speciale.\""}
