MultiLanguageSpellData['it'][401119] = {name = "Lancia Fiammeggiante", additional_info = "Portata illimitata\nIstantaneo\n[q]Il cacciatore prende di mira diversi personaggi, scagliando una Lancia Fiammeggiante che inizialmente infligge 238844 danni fisici ai personaggi entro 6 m dal punto d'impatto.\n\n La Lancia Fiammeggiante rimane conficcata a terra e dopo qualche istante esplode, infliggendo 286504 danni da fuoco ai personaggi entro 8 m."}
MultiLanguageSpellData['it'][401122] = {name = "Luna Crescente", additional_info = "Canalizzato (3 s di lancio)\n[q]Soffia un cono di energia magica, infliggendo danni da arcano."}
MultiLanguageSpellData['it'][401123] = {name = "Tempesta di Lame Selvaggia", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion spinge il Guerriero a lanciare una Tempesta di Lame Selvaggia ogni 6 s per 30 s, infliggendo 25 danni fisici inflitti a tutti i personaggi e alle creature entro 8 m ogni 1 s per 4 s."}
MultiLanguageSpellData['it'][401124] = {name = "Esecuzione Zelante", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion corrompe la fede del Paladino, obbligandolo a richiamare un martello dalla luce ogni 6 s per 30 s. Il martello consacra il terreno, infliggendo 10 danni da sacro a qualsiasi bersaglio nell'area d'effetto e infliggendo 50 danni da sacro quando il martello atterra dopo 5 s."}
MultiLanguageSpellData['it'][401125] = {name = "Bestie Corrotte", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion costringe il Cacciatore a richiamare famigli corrotti dalle stalle, obbligandoli ad attaccare.\n\n Quando abbatte un famiglio corrotto, il cacciatore viene potenziato da Oscurità Scatenata ."}
MultiLanguageSpellData['it'][401126] = {name = "Tradimento Selvaggio", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion corrompe la natura traditrice del Ladro, inducendolo a comparire alle spalle di un alleato ogni 10 s e a lanciare pugnali contro tutti i bersagli entro 10 m, infliggendo 20 danni fisici. Inoltre, affligge tutti i bersagli colpiti con Veleno Selvatico ."}
MultiLanguageSpellData['it'][401127] = {name = "Urlo Disperato", additional_info = "Portata illimitata\nIstantaneo\n[q]La corruzione di Neltharion fa vacillare la fede del Sacerdote, obbligandolo a emettere un Urlo Disperato ogni 6 s per 30 s, infliggendo 7 danni da ombra ogni 1 s ai personaggi e alle creature entro 8 m e costringendoli a fuggire in preda al terrore per 6 s.\n\n Il Sacerdote ottiene 1 accumulo di Parola d'Ombra: Perfidia per ogni bersaglio colpito, fino a un massimo di 5."}
MultiLanguageSpellData['it'][401128] = {name = "Presa Selvaggia", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion ottiene il controllo dei poteri della Non Morte del Cavaliere della Morte, obbligandolo a creare pozze di Pestilenza Selvaggia e a lanciare Presa Mortale sugli alleati ogni 10 s per 30 s."}
MultiLanguageSpellData['it'][401129] = {name = "Totem dell'Elementale dell'Ombra", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion costringe lo Sciamano a evocare dei totem per vincolare le ombre elementali che attaccano.\n\n Dopo aver sconfitto un elementale, lo Sciamano viene potenziato da Oscurità Scatenata ."}
MultiLanguageSpellData['it'][401130] = {name = "Magia Selvaggia", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion corrompe il flusso di energie arcane nel Mago, costringendolo a eruttare Magia Selvaggia ogni 10 s per 30 s, infliggendo 20 danni da arcano ai personaggi e alle creature entro 10 m ogni 0.5 s per 4 s."}
MultiLanguageSpellData['it'][401131] = {name = "Evocazione Selvaggia", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion costringe lo Stregone a evocare allucinazioni di Bestie del Vuoto Voraci che attaccano lo Stregone per 25 s.\n\n Quando lo Stregone uccide una di queste bestie, viene potenziato da Oscurità Scatenata ."}
MultiLanguageSpellData['it'][401132] = {name = "Spirito, Acqua e Decadimento", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion corrompe l'essenza del Monaco, facendo sì che gli spiriti si dividano e attacchino per 30 s.\n\n Sconfiggendo uno di questi spiriti, il Monaco viene potenziato da Oscurità Scatenata ."}
MultiLanguageSpellData['it'][401133] = {name = "Sfasamento Selvaggio", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion sfrutta la connessione del Druido con la natura, obbligandolo a mutare forma in una forma casuale ogni 10 s per 30 s. La violenza ferina della mutazione provoca al Druido Falciata Selvaggia e gli fornisce Fervore del Mutaforma ."}
MultiLanguageSpellData['it'][401134] = {name = "Danza del Caos", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion costringe il Cacciatore di Demoni a eruttare in una caotica danza delle lame ogni 6 s per 30 s, infliggendo 20 danni da caos a tutte le creature e ai personaggi entro 8 m più volte."}
MultiLanguageSpellData['it'][401135] = {name = "Soffio Selvaggio", additional_info = "Portata illimitata\nIstantaneo\n[q]Neltharion prende il controllo dell'Evocatore, obbligandolo a lanciare Soffio Selvaggio ogni 6 s per 30 s, infliggendo 10 danni da fuoco a tutti i personaggi mentre vola sul campo di battaglia."}
