MultiLanguageSpellData['it'][405118] = {name = "Pietra del Flusso Emanante", additional_info = "Portata di 30 m\nIstantaneo\n[q]Ricevere cure fornisce una probabilità di emanare vapore, rigenerando 623 salute a se stessi e a 2 alleati vicini."}
MultiLanguageSpellData['it'][405120] = {name = "Deposito Metamorfico di Serevite", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La serevite è il minerale più comune di tutte le Isole dei Draghi. Anche se si trova più spesso nelle regioni di montagna, può essere rinvenuta anche vicino ai corsi d'acqua.\n\n I depositi di minerali in stato metamorfico attivo si possono trovare solo nella Caverna di Zaralek.\n\n Fornisce il seguente effetto quando si estraggono minerali:\n\n Polvere Lucente di Zaralek :\nTi ricopre di polvere luminosa, perfetta per aiutare la propagazione delle spore. Dura 2 min."}
MultiLanguageSpellData['it'][405121] = {name = "Deposito Metamorfico di Draconium", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere.\n\n I depositi di minerali in stato metamorfico attivo si possono trovare solo nella Caverna di Zaralek.\n\n Fornisce il seguente effetto quando si estraggono minerali:\n\n Polvere Lucente di Zaralek :\nTi ricopre di polvere luminosa, perfetta per aiutare la propagazione delle spore. Dura 2 min."}
MultiLanguageSpellData['it'][405122] = {name = "Maleficio Crostaceo", additional_info = nil}
MultiLanguageSpellData['it'][405123] = {name = "Altofiore Tremolante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]L'Altofiore è l'erba più comune di tutte le Isole dei Draghi. La si può trovare praticamente ovunque e su qualsiasi terreno.\n\n Le erbe in stato tremolante si possono trovare solo nella Caverna di Zaralek.\n\n Fornisce il seguente effetto quando si raccolgono erbe:\n\n Lucentezza di Zaralek :\nTi ricopre di spore luminose che non vedono l'ora di propagarsi. Dura 2 min."}
MultiLanguageSpellData['it'][405124] = {name = "Papavero Bolla Tremolante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il Papavero Bolla è un'erba delicata che cresce nelle zone acquatiche delle Isole dei Draghi, quindi lungo i fiumi, sulle coste e nelle caverne umide.\n\n Nonostante il suo aspetto unico il Papavero Bolla non è particolarmente utile. La cosa veramente preziosa è il fungo acquoso che si forma alla sua base.\n\n Le erbe in stato tremolante si possono trovare solo nella Caverna di Zaralek.\n\n Fornisce il seguente effetto quando si raccolgono erbe:\n\n Lucentezza di Zaralek :\nTi ricopre di spore luminose che non vedono l'ora di propagarsi. Dura 2 min."}
MultiLanguageSpellData['it'][405125] = {name = "Corrente a Getto", additional_info = "Portata di 100 m\nIstantaneo\n[q]L'incantatore canalizza ondate ad alta pressione davanti e dietro di sé, infliggendo 12 danni da gelo ai nemici e respingendoli indietro.\n\n Le onde ruotano attorno all'incantatore durante la canalizzazione."}
MultiLanguageSpellData['it'][405126] = {name = "Sassifraga Tremolante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Le erbe in stato tremolante si possono trovare solo nella Caverna di Zaralek.\n\n Fornisce il seguente effetto quando si raccolgono erbe:\n\n Lucentezza di Zaralek :\nTi ricopre di spore luminose che non vedono l'ora di propagarsi. Dura 2 min."}
MultiLanguageSpellData['it'][405127] = {name = "Scorzatorta Tremolante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La scorzatorta è un'erba verdeggiante che si trova sulle Isole dei Draghi. Si trova dove c'è abbondanza di alberi o foglie.\n\n Le erbe in stato tremolante si possono trovare solo nella Caverna di Zaralek.\n\n Fornisce il seguente effetto quando si raccolgono erbe:\n\n Lucentezza di Zaralek :\nTi ricopre di spore luminose che non vedono l'ora di propagarsi. Dura 2 min."}
