MultiLanguageSpellData['it'][408649] = {name = "Alaroccia d'Ombrofuoco", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Nato dal magma, il suo carapace era originariamente fatto di grumi fusi di roccia vulcanica raffreddata. Essere infuso dall'ombrofuoco non ha fatto che solidificare ulteriormente la sua natura indistruttibile.\"\nImpresa:\nGloria dell'incursore dell'Aberrus"}
MultiLanguageSpellData['it'][408650] = {name = "Armardente", additional_info = nil}
MultiLanguageSpellData['it'][408651] = {name = "Alaroccia Catalogato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Il primo esemplare di alaroccia fiammeggiante mai scoperto. Nove ricercatori su dieci confermano: è caldo!\"\nZona:\nCaverna di Zaralek\nEvento pubblico:\nRicercatori Sotto Attacco"}
MultiLanguageSpellData['it'][408652] = {name = "Ululato Infuocato", additional_info = "Ululato Infuocato Livello 80\n[q0][Item Effect]{Istantaneo} {1.5 min di recupero}\n[q]Richiama un segugio che lancia un ululato infuocato, aumentando il tuo indice di critico di 205 per 20 s."}
MultiLanguageSpellData['it'][408653] = {name = "Trasportamassi", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questi alaroccia sono stati addestrati per trasportare grandi quantità di Macigni per Baratto per le attività di scambio dei Niffen.\"\nMercante:\nPonzo\nZona:\nCaverna di Zaralek\nCosto:\n85"}
MultiLanguageSpellData['it'][408654] = {name = "Alaroccia Sabbioso", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I motivi sulle ali della creatura ricordano la sabbia che scorre attraverso una clessidra. Li si potrebbe stare a fissare per anni...\"\nMercante:\nQualsiasi Mercante dei Viaggi nel Tempo\nCosto:\n5.000"}
MultiLanguageSpellData['it'][408655] = {name = "Bestia da Fiuto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Una razza di alaroccia addestrati dai Niffen per trovare i bocconcini più profondi.\"\nMercante:\nHarlowe Marl\nZona:\nCaverna di Zaralek\nCosto:\n800"}
