MultiLanguageSpellData['it'][409438] = {name = "Colpo Sismico", additional_info = "Portata di 100 m\nIstantaneo\n[q]Smottamento fa sì che i nemici a mezz'aria vengano scaraventati a terra, stordendoli per 4 s. Riduce il tempo di recupero di Smottamento di 15 s."}
