MultiLanguageSpellData['it'][414177] = {name = "Annientamento Cataclismico", additional_info = "Istantaneo\n[q]Iridikron scatena un'esplosione cataclismica che infligge 1212224691 danni da natura a tutti i personaggi. Questi danni non possono essere evitati.\n\n Mentre si prepara ad attaccare, infligge 1818337 danni da natura a tutti i personaggi ogni 1.5 s.\n\n Iridikron perde energia quando subisce danni e non può lanciare quest'abilità se raggiunge 0 energia. Cromie lancia Trascendenza della Linea Temporale per aiutare i suoi alleati."}
MultiLanguageSpellData['it'][414178] = {name = "Trascendenza della Linea Temporale", additional_info = "Portata illimitata\nIstantaneo\n[q]Cromie genera una bolla di distorsione temporale, fornendo ai personaggi il loro potenziale massimo futuro.\n\n Aumenta i danni inflitti del 100%, la celerità del 100%, la velocità di recupero del 100% e la velocità di rigenerazione delle risorse del 100%.\n\n Cromie può farlo solo una volta senza rischiare una convergenza temporale permanente."}
