MultiLanguageSpellData['it'][414316] = {name = "Lupo da Guerra Bianco", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Lupo da Guerra Bianco cavalcabile.\n[q]\"La fame di un lupo può mai essere saziata? Questi lupi brutali cercano e divorano i nemici dell'Orda.\"\nOrda\nBottino:\nFenditure del Tempo\nMercante:\nCustode Krizzik\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000\n\nAlleanza\nOggetto:\nDono del Lupo da Guerra Bianco"}
