MultiLanguageSpellData['it'][414323] = {name = "Grifone Nero Vorace", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"La guerra ha corrotto queste creature, un tempo orgogliose. I sussurri delle loro ali ora raccontano presagi di imminente sconfitta.\"\nAlleanza\nBottino:\nFenditure del Tempo\nMercante:\nCustode Krizzik\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000\n\nOrda\nOggetto:\nDono del Grifone Nero Vorace"}
MultiLanguageSpellData['it'][414324] = {name = "Albatros dalle Zampe Dorate", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Arrivata volteggiando da un lontano flusso temporale, questa variante mai vista prima è nata in un mondo devoto all'ordine.\"\nBottino:\nFenditure del Tempo\nMercante:\nSorotis\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
MultiLanguageSpellData['it'][414326] = {name = "Drago della Viltempesta", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"La Legione Infuocata ha sconfitto i draghi in un lontano flusso temporale. Questi vildragoni hanno preferito la corruzione e la schiavitù alla distruzione.\"\nBottino:\nFenditure del Tempo\nMercante:\nFalara Cantanotte\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
MultiLanguageSpellData['it'][414327] = {name = "Segugio Sulfureo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Segugio Sulfureo cavalcabile.\n[q]\"L'Impero Nero ha soggiogato questi segugi umiliati e denigrati. Assolutamente obbedienti, servono con ancora più forza.\"\nBottino:\nFenditure del Tempo\nMercante:\nApprovvigionatrice Qorra\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
MultiLanguageSpellData['it'][414328] = {name = "Mastodonte Perfetto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Mastodonte Perfezionato.\n[q]\"La perfezione, come la bellezza, è nell'occhio di chi guarda. Ma la vista può essere chirurgicamente potenziata.\"\nBottino:\nFenditure del Tempo\nMercante:\nVella la Trivella\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
