MultiLanguageSpellData['it'][421045] = {name = "Schegge di Carbone", additional_info = "Portata illimitata\nIstantaneo\n[q]Pezzi di carbone in fiamme volano via dal corpo di Torciradice, infliggendo 36262 danni da ombrofuoco ai personaggi entro 5 m dal punto d'impatto e affliggendoli con Bruciato dalla Brace .\n\n Ogni pezzo di carbone che non colpisce un personaggio esplode al contatto col terreno, infliggendo 108785 danni da ombrofuoco a tutti i personaggi."}
