MultiLanguageSpellData['it'][421224] = {name = "Altofiore In Fiore", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]L'Altofiore è l'erba più comune di tutte le Isole dei Draghi. La si può trovare praticamente ovunque e su qualsiasi terreno.\n\n Alcune erbe che crescono all'interno del Sogno sono senzienti e non apprezzeranno di essere raccolte. Si sradicheranno e fuggiranno dai loro aspiranti raccoglitori, ma chi mostra abbastanza determinazione potrebbe comunque riuscire a raccogliere materiali da queste creature."}
MultiLanguageSpellData['it'][421225] = {name = "Tracciamento Percorso", additional_info = "[q0][Item Effect]{Istantaneo} {30 min di recupero}\n[q]Rilascia periodicamente anelli per farci correre attraverso i membri del gruppo.\n\n Gli anelli non possono essere piazzati troppo vicini gli uni agli altri. Tempo di recupero ridotto durante la Vigilia di Grande Inverno."}
MultiLanguageSpellData['it'][421226] = {name = "Sassifraga In Fiore", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La Sassifraga è un'erba robusta che può crescere in diversi luoghi. Nonostante sia generalmente diffusa nei luoghi più impervi, come montagne o scogliere, si trova anche nelle pianure o nelle regioni vulcaniche.\n\n Alcune erbe che crescono all'interno del Sogno sono senzienti e non apprezzeranno di essere raccolte. Si sradicheranno e fuggiranno dai loro aspiranti raccoglitori, ma chi mostra abbastanza determinazione potrebbe comunque riuscire a raccogliere materiali da queste creature."}
MultiLanguageSpellData['it'][421227] = {name = "Scorzatorta In Fiore", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]La scorzatorta è un'erba verdeggiante che si trova sulle Isole dei Draghi. Si trova dove c'è abbondanza di alberi o foglie.\n\n Alcune erbe che crescono all'interno del Sogno sono senzienti e non apprezzeranno di essere raccolte. Si sradicheranno e fuggiranno dai loro aspiranti raccoglitori, ma chi mostra abbastanza determinazione potrebbe comunque riuscire a raccogliere materiali da queste creature."}
MultiLanguageSpellData['it'][421228] = {name = "Spirale di Fiamme", additional_info = "Portata illimitata\nIstantaneo\n[q]Fiamme serpentine vorticano attorno al personaggio, infliggendo 4 danni da fuoco e irradiando Bruciatura Vorticosa sui personaggi vicini ogni 1 s per 12 s. Le fiamme si stringono nel tempo, aumentando i danni man mano che l'area si riduce."}
