MultiLanguageSpellData['it'][421244] = {name = "Deposito Vivente di Serevite", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La serevite è il minerale più comune di tutte le Isole dei Draghi. Anche se si trova più spesso nelle regioni di montagna, può essere rinvenuta anche vicino ai corsi d'acqua.\n\n Depositi minerari che sono stati influenzati dalle potenti forze naturali del Sogno prendono vita, in fuga dagli aspiranti raccoglitori."}
MultiLanguageSpellData['it'][421245] = {name = "Ruggito Assonnato", additional_info = "Portata di 100 m\nCanalizzato (3.5 s di lancio)\n[q]Aurostor ruggisce, infliggendo 69475 danni da natura a tutti i nemici. Inoltre, i personaggi subiscono 3 accumuli di Ruggito Assonnato e la loro velocità di movimento si riduce del 25% per accumulo per 14 s.\n\n Saltare rimuove un accumulo di Ruggito Assonnato ."}
MultiLanguageSpellData['it'][421247] = {name = "Deposito Vivente di Draconium", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]I Depositi di Draconium sono rari da trovare sulle Isole dei Draghi, ma sono più spesso visibili nei luoghi più difficili da raggiungere.\n\n Depositi minerari che sono stati influenzati dalle potenti forze naturali del Sogno prendono vita, in fuga dagli aspiranti raccoglitori."}
