MultiLanguageSpellData['it'][422850] = {name = "Death Knight Blood 10.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Consumare potenza runica fornisce una probabilità di far sì che il successivo Assalto al Cuore applichi Decadimento Cinereo, riducendo i danni a te inflitti del 10% e aumentando i danni da te inflitti ai bersagli affetti del 20% per 8 s."}
MultiLanguageSpellData['it'][422851] = {name = "Death Knight Blood 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]I danni finali inflitti da Mietitura dell'Anima e i danni inflitti da Arto di Abominio applicano Decadimento Cinereo ai bersagli nemici. I danni diretti inflitti da Assalto al Cuore ed Ebollizione del Sangue aumentano la durata di Decadimento Cinereo di 1.0 s."}
