MultiLanguageSpellData['it'][422858] = {name = "Distintivo dell'Amicizia di Smeraldo di Pip", additional_info = "Distintivo dell'Amicizia di Smeraldo di Pip Livello 80\n[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Unisciti alla Squadra dei Sogni, ottenendo ( 266 / 12) dell'indice di maestria di Pip, dell'indice di versatilità di Urctos o dell'indice di critico di Arewynn, in base a chi è il tuo attuale Migliore Amico.\n\n Gli incantesimi e le abilità hanno una probabilità di stabilire un nuovo Migliore Amico casuale, fornendo il suo bonus passivo e potenziandolo a 266 prima che l'effetto decada in 12 s.\n(12s di recupero)"}
MultiLanguageSpellData['it'][422859] = {name = "Demon Hunter Havoc 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Lancio Lama riduce il tempo di recupero rimasto di A Caccia di 2.0 s e aumenta la durata dell'effetto dannoso periodico di A Caccia di 6 s."}
