MultiLanguageSpellData['it'][422893] = {name = "Paladin Holy 10.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Quando Barlume di Luce si dissipa o viene rinnovato, crea un Riverbero Sacro sul bersaglio, curando un alleato di ([108% of Spell Power]) o infliggendo ([96% of Spell Power]) danni a un nemico in 8 s. Diversi Riverberi Sacri potrebbero sovrapporsi fino a 6 volte."}
