MultiLanguageSpellData['it'][422910] = {name = "Rogue Subtlety 10.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Usare Sventramento, Perforazione o Polvere Nera fornisce una probabilità di evocare un clone d'ombra che ripete la mossa risolutiva, infliggendo il 70% di danni da ombra aggiuntivi."}
