MultiLanguageSpellData['it'][422918] = {name = "Warlock Affliction 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Putrefazione d'anima fornisce 3 cariche di Combustione Ombrosa, che aumenta i danni inflitti dalla successiva Estasi Malefica del 50% o dal successivo Seme della Corruzione del 60%. Inoltre, Combustione Ombrosa fa sì che Estasi Malefica estenda la durata degli effetti dannosi periodici e di Tormento di 2 s."}
MultiLanguageSpellData['it'][422919] = {name = "Warlock Demonology 10.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Consumare un Nucleo Demoniaco applica un Marchio Demoniaco che esplode dopo 20 s, infliggendo ([268.747% of Spell Power]) danni da ombra ai nemici vicini o [([268.747% of Spell Power]) * (2.25)] danni da ombra a un singolo nemico. Mano di Gul'dan riduce la durata dei Marchi Demoniaci di 1 s per ogni frammento d'anima consumato."}
MultiLanguageSpellData['it'][422920] = {name = "Warlock Demonology 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Quando Marchio Demoniaco viene rimosso, fornisce una probabilità di evocare un Demonio della Rovina che lancia 5 Raffiche di Dardi della Rovina prima di scomparire. Ogni Raffica di Dardi della Rovina infligge [(1.553369999\n * (Potenza Magica * 1) * 1 * (1 + Versatilità)) * 1.169617819] danni da ombra a un massimo di 4 nemici o [((1.553369999\n * (Potenza Magica * 1) * 1 * (1 + Versatilità)) * 1.169617819) * (2.1)] danni da ombra a un singolo nemico."}
MultiLanguageSpellData['it'][422921] = {name = "Warlock Destruction 10.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]I dardi delle Fenditure Dimensionali infliggono il 25% dei danni inflitti ai nemici vicini. i danni periodici di Immolazione hanno una probabilità di fornire una carica di Fenditura Dimensionale."}
MultiLanguageSpellData['it'][422922] = {name = "Warlock Destruction 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Fenditura Dimensionale può evocare una potente Fenditura Infuocata che scaglia 20 Dardi Roventi che infliggono ([56.9622% of Spell Power]) danni da fuoco istantaneamente e ([22.793% of Spell Power]) danni da fuoco aggiuntivi in 10 s."}
MultiLanguageSpellData['it'][422923] = {name = "Warrior Arms 10.2 Class Set 2pc", additional_info = "[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Aumenta i danni inflitti da Squartamento del 30%. Inoltre, Morte Improvvisa può essere attivata dai danni da sanguinamento di Squartamento."}
MultiLanguageSpellData['it'][422924] = {name = "Warrior Arms 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Morte Improvvisa fa sì che la successiva Esecuzione colpisca il terreno, provocando uno Schianto del Tuono che infligge il 200% di danni aggiuntivi. Inoltre, il bersaglio di Esecuzione subisce danni da sanguinamento pari al 50% dei danni inflitti da Esecuzione in 5 s. Se l'effetto di sanguinamento viene riapplicato, i danni restanti si aggiungono al nuovo effetto.\n(500ms di recupero)"}
MultiLanguageSpellData['it'][422925] = {name = "Warrior Fury 10.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Furia di Odyn infligge il 50% di danni aggiuntivi e fa sì che le successive 3 Brame di Sangue infliggano il 150% di danni aggiuntivi e abbiano una probabilità di critico aggiuntiva del 100% contro il bersaglio primario."}
MultiLanguageSpellData['it'][422926] = {name = "Warrior Fury 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]I colpi critici di Brama di Sangue riducono il tempo di recupero di Furia di Odyn di 2.5 s.\n(500ms di recupero)"}
MultiLanguageSpellData['it'][422927] = {name = "Warrior Protection 10.2 Class Set 2pc", additional_info = "[q0][Item Effect][q]Consumare rabbia fornisce una probabilità che il successivo Colpo di Scudo consumi i tuoi effetti di sanguinamento su un bersaglio, infliggendo istantaneamente il 40% dei danni restanti degli effetti di Ferite Profonde e Squartamento, e il 100% dell'effetto di Rombo di Tuono, riducendo i danni da te subiti del 10% per 5 s."}
MultiLanguageSpellData['it'][422928] = {name = "Warrior Protection 10.2 Class Set 4pc", additional_info = "[q0][Item Effect][q]Per ogni effetto di sanguinamento consumato da un bersaglio, i danni da te subiti si riducono del 2% aggiuntivo. Quando Colpo di Scudo consuma un effetto di sanguinamento, il tempo di recupero di Schianto del Tuono si azzera e il tempo di recupero di Rombo di Tuono si riduce di 3.0 s."}
