MultiLanguageSpellData['it'][429641] = {name = "Sorti della Battaglia", additional_info = "[q]Armi\n Vigore Colossale aumenta i danni inflitti da Dominazione del 5% per accumulo.\n\nProtezione\n Vigore Colossale aumenta i danni inflitti da Rivincita del 7% per accumulo."}
