MultiLanguageSpellData['it'][430607] = {name = "Tonico Malvagio degli Spiriti Classici", additional_info = "2 s di lancio 2\nReagenti:\nTonico Malvagio dell'Onore , Orbinide (6)\nMercante:\nHotharn\nZona:\nDornogal\nCosto:\n7.500\n\n[q2]Usa: Bere permette di aumentare la rigenerazione di mana del 8% quando non si lancia alcun incantesimo benefico che consumi mana per 5 s.\n\n Punti Onore ottenuti aumentati del 15%.\n\nDura 1 ora e persiste oltre la morte. Consumare un secondo tonico identico aggiunge 1 ora.\n71"}
MultiLanguageSpellData['it'][430608] = {name = "Tonico Malvagio dell'Onore", additional_info = "2 s di lancio 2\nReagenti:\nMicofiore (16), Bocciolo della Benedizione (8), Fiala Dorata (2)\nMercante:\nHotharn\nZona:\nDornogal\nCosto:\n7.500\n\n[q2]Usa: Bere permette di aumentare i Punti Onore ottenuti del 15%. Può essere usato in tutti i contesti PvP classificati e non classificati.\n\nDura 1 ora e persiste oltre la morte. Consumare un secondo tonico identico aggiunge 1 ora.\n71"}
