MultiLanguageSpellData['it'][432775] = {name = "Sorgente Congelata", additional_info = "Sorgente Congelata Livello 80\n[q0][Item Effect]Portata di 100 m\n{Istantaneo} {2 min di recupero}\n[q]Infonde le abilità con i poteri del globo, ottenendo 50 cariche di Sorgente Congelata. Infliggere danni consuma una carica, che infligge 23 danni da gelo aggiuntivi e applica accumuli di Gelo di Sorgente, rallentando la velocità di movimento del nemico del 2% per accumulo.\n\n Quando Sorgente Congelata viene completamente consumata, frantuma tutti i bersagli affetti da Gelo della Sorgente, infliggendo 76 danni da gelo per accumulo suddivisi tra tutti i bersagli vicini."}
MultiLanguageSpellData['it'][432777] = {name = "Tomo del Potere Instabile", additional_info = "Tomo del Potere Instabile Livello 80\n[q0][Item Effect]Circa 1.5 apparenze ogni minuto\n[q]Gli incantesimi d'attacco hanno una probabilità di creare 1-3 Illusioni Arcane di se stessi che canalizzano per 3 s prima di scatenare Sbarramento Arcano sulla posizione del bersaglio, infliggendo fino a ( 1343 * 1.1) danni da arcano a tutti i nemici nell'area d'effetto."}
MultiLanguageSpellData['it'][432778] = {name = "Intelletto Arcano", additional_info = "Portata di 40 m\nIstantaneo\n[q]Infonde intelligenza nel bersaglio, aumentandone l'Intelletto del 5% per 1 ora.\n\n Se il bersaglio è un membro del gruppo o dell'incursione, tutti i membri del gruppo o dell'incursione ne saranno affetti."}
