MultiLanguageSpellData['it'][434132] = {name = "Benedizione della Forgia", additional_info = "Portata di 100 m\nIstantaneo\n[q]Ira Vendicatrice evoca un'Arma Sacra aggiuntiva e durante Ira Vendicatrice l'Arma Sacra lancia incantesimi sui bersagli e fa riecheggiare gli effetti delle tue abilità che consumano cariche di potere sacro."}
