MultiLanguageSpellData['it'][434137] = {name = "Spruzzo Velenoso", additional_info = "Portata di 60 m\n3 s di lancio\n[q]L'incantatore rilascia una scarica di veleno letale, infliggendo 909169 danni da natura a tutti i personaggi ogni 1 s per 12 s.\n\n L'incantatore poi canalizza per 9 s, facendo piovere globuli di veleno che infliggono 7273348 danni da natura ai personaggi entro 3 m dai punti d'impatto."}
