MultiLanguageSpellData['it'][434151] = {name = "Esortazione Terrificante", additional_info = "[q]Empietà\n Assalto Vampirico e aumentano i danni da ombra subiti dai bersagli del 1%, fino a un massimo del 5% per 15 s.\n\n Assalto Vampirico beneficia di Esortazione Terrificante al 400% dell'efficacia.\n\nSangue\n Assalto Vampirico e Assalto al Cuore aumentano i danni da ombra subiti dai bersagli del 1%, fino a un massimo del 5% per 15 s.\n\n Assalto Vampirico beneficia di Esortazione Terrificante al 400% dell'efficacia."}
MultiLanguageSpellData['it'][434152] = {name = "Dono dei San'layn", additional_info = "[q]Sangue\n Quando l'effetto di Arma Runica Danzante è attivo, si ottiene Dono dei San'layn.\n\n Dono dei San'layn aumenta l'efficacia di Essenza della Regina del Sangue del 200% e fa sì che Assalto Vampirico sostituisca Assalto al Cuore per tutta la durata dell'effetto.\n\nEmpietà\n Quando l'effetto di Trasformazione Oscura è attivo, si ottiene Dono dei San'layn.\n\n Dono dei San'layn aumenta l'efficacia di Essenza della Regina del Sangue del 100% e fa sì che Assalto Vampirico sostituisca per tutta la durata dell'effetto."}
MultiLanguageSpellData['it'][434153] = {name = "Dono dei San'layn", additional_info = "Istantaneo\n[q]Sangue\nQuando l'effetto di Arma Runica Danzante è attivo, si ottiene Dono dei San'layn.\n\n Dono dei San'layn aumenta l'efficacia di Essenza della Regina del Sangue del 200% e fa sì che Assalto Vampirico sostituisca Assalto al Cuore per tutta la durata dell'effetto.\n\nEmpietà\nQuando l'effetto di Trasformazione Oscura è attivo, si ottiene Dono dei San'layn.\n\n Dono dei San'layn aumenta l'efficacia di Essenza della Regina del Sangue del 100% e fa sì che Assalto Vampirico sostituisca per tutta la durata dell'effetto."}
MultiLanguageSpellData['it'][434155] = {name = "Lame Fasiche", additional_info = "Portata illimitata\nIstantaneo\n[q]Sikran marchia i personaggi e scatta verso ogni bersaglio marchiato, infliggendo 3741605 danni fisici a chiunque lungo la traiettoria.\n\n Inoltre, riduce le cure ricevute dai personaggi colpiti del 50% e infligge 474896 danni da ombra aggiuntivi ogni 2 s per 20 s.\n\n I bersagli marchiati lasciano dietro di sé un Simulacro Cosmico quando vengono colpiti."}
MultiLanguageSpellData['it'][434156] = {name = "Incarichi di Lavoro", additional_info = "[q0][Item Effect]Portata di 15 m\n{0.5 s di lancio} {3 s di recupero}\n[q]Consegna gli Incarichi di Lavoro di Merrix ai Lavoratori Svincolati."}
MultiLanguageSpellData['it'][434157] = {name = "Forza Viscerale", additional_info = "[q]Empietà\n Quando l'effetto Condanna Improvvisa viene consumato, aumenta la Forza del 8% per 5 s.\n\n Quando Assalto del Flagello consuma Piaga Virulenta, il successivo Contagio non ha alcun costo in rune e lancia Spira Mortale o Epidemia (l'incantesimo usato più di recente) al 100% dell'efficacia.\n\nSangue\n Quando l'effetto Flagello Cremisi viene consumato, aumenta la Forza del 12% per 12 s.\n\n Quando Ebollizione del Sangue colpisce 2 o più bersagli, fornisce 1 carica di Scudo d'Ossa."}
