MultiLanguageSpellData['it'][435103] = {name = "Destriero del Vento Scattante", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"I Destrieri del Vento sono incredibilmente gentili e facili da addestrare... se riesci a catturarne uno.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435105] = {name = "Tracciamento Missione", additional_info = nil}
MultiLanguageSpellData['it'][435107] = {name = "Destriero del Vento Boschivo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Il manto di questo Destriero del Vento non si limita a essere colorato per abbinarsi alla sua terra natia, ma di solito contiene anche pezzi di corteccia e foglie.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435108] = {name = "Destriero del Vento della Tempesta Diurna", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Si dice che quando il fulmine colpirà il sole, una bestia scintillante in armatura rossa discenderà dal cielo. Il Destriero del Vento della Tempesta Diurna non ha mai sentito parlare di queste leggende ed è stato qui tutto il tempo.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435109] = {name = "Solcavento Piumato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Controllare la velocità attuale e l'elevazione prima della salita a bordo. Evitare alberi e altri oggetti alti. Non è concesso di restituire o chiedere il rimborso degli aquiloni danneggiati.\" - Manuale di Istruzioni del Vento\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435110] = {name = "Estrazione", additional_info = nil}
MultiLanguageSpellData['it'][435114] = {name = "Nessun Proprietario", additional_info = nil}
MultiLanguageSpellData['it'][435115] = {name = "Guardiano Quilen", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Quando Quan l'Implacabile cadde in battaglia, i suoi fedeli segugi aspettarono il suo ritorno. Millenni dopo, attendono pazienti.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435118] = {name = "Quilen Marmoreo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Creato da un Occultista Mogu che ha dato vita alla sua pietra preferita.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435119] = {name = "Turbine Telato", additional_info = "Portata di 300 m\nIstantaneo\n[q]Ulgrax sputa ragnatele contro un personaggio e tutti gli alleati entro 10 m, infliggendo 17331401 danni da natura suddivisi equamente tra tutti i personaggi, vincolandoli a Ulgrax.\n\n I personaggi vincolati subiscono 575632 danni da natura ogni 2 s e vengono trascinati verso Ulgrax. La forza con cui Ulgrax trascina i personaggi di riduce all'aumentare dei personaggi vincolati."}
MultiLanguageSpellData['it'][435123] = {name = "Gru Cavalcabile Aurea", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Si dice che un imperatore una volta pagò una grossa somma per una gru dorata. Dopo aver scoperto che la gru fosse solo tinta del prezioso metallo, si nascose nelle sue stanze per una settimana in preda alla vergogna.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435124] = {name = "Gru Cavalcabile Lussuosa", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Un uccello maestoso, ma un po' schizzinoso.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435125] = {name = "Gru Cavalcabile Tropicale", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questo nativo della Foresta di Giada usa la sua colorazione per mimetizzarsi.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435126] = {name = "Gru Cavalcabile Argentea", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questo alto uccello è tra le più aggraziate ed eleganti delle gru, leggermente più della Gru di Bronzo ma leggermente meno della Gru Dorata.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435127] = {name = "Gru Cavalcabile Rosa", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questo uccello colorato è spesso confuso con un fenicottero o un marabù.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435128] = {name = "Gru Cavalcabile Chiara", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Ed ecco, mi apparve... una gru pallida?\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435129] = {name = "Condimento dello Chef", additional_info = "Portata di 100 m\nIstantaneo\n[q]Lo chef condisce tutti i personaggi con del sale, infliggendo 4 danni fisici ogni 1.5 s e aumentandone tutti i danni subiti del 10% per 9 s.\n\n Si accumula."}
