MultiLanguageSpellData['it'][435138] = {name = "Acido Digestivo", additional_info = "Portata di 300 m\n2 s di lancio\n[q]Ulgrax vomita Acido Digestivo su diversi personaggi, infliggendo 1726895 danni da natura ogni 2 s per 6 s.\n\n Se dissolto, il veleno fuoriesce dalla pelle della vittima, infliggendo 1151263 danni da natura ai personaggi entro 7 m e dissolvendo ogni ragnatela rimasta dalle Ragnatele Predatorie ."}
