MultiLanguageSpellData['it'][435143] = {name = "Lame Fasiche", additional_info = "Portata illimitata\nCanalizzato (1.5 s di lancio)\n[q]Sikran marchia i personaggi e scatta verso ogni bersaglio marchiato, infliggendo 3741605 danni fisici a chiunque lungo la traiettoria.\n\n Inoltre, riduce le cure ricevute dai personaggi colpiti del 50% e infligge 474896 danni da ombra aggiuntivi ogni 2 s per 20 s.\n\n I bersagli marchiati lasciano dietro di sé un Simulacro Cosmico quando vengono colpiti."}
MultiLanguageSpellData['it'][435144] = {name = "Schegge Impalanti", additional_info = "[q]Ogni volta che lo scudo di Permagelo subisce danni, fornisce una probabilità di scagliare schegge di ghiaccio contro i nemici vicini, infliggendo ([5% of Attack Power]) danni da gelo e riducendo i danni a te inflitti da questi bersagli del 5% per 5 s."}
MultiLanguageSpellData['it'][435145] = {name = "Urlacieli Insanguinato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questo dinosauro cova ancora il rancore dei suoi antenati dall'invasione degli Zandalari.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435146] = {name = "Pterrordattilo Notturno", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Gli studiosi interpretano il terribile stridio di questa creatura come: \"Temetemi, io sono la notte!\"\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435147] = {name = "Pterrordattilo di Giada", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questa cavalcatura preferita dagli Zandalari ha una voce meravigliosa, o almeno così crede.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435148] = {name = "Assalto Fiammeggiante", additional_info = "Portata di 8 m\n1.5 s di lancio\n[q]Infligge 4848899 danni da sacro istantaneamente e 484890 danni da sacro aggiuntivi ogni 1 s per 10 s."}
MultiLanguageSpellData['it'][435149] = {name = "Mastodonte di Cobalto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Ciò che iniziò come una macchina cavalcabile d'estrazione e di registrazione divenne rapidamente portatrice di caos quando gli ingegneri si chiesero se avrebbero potuto renderla ancora più interessante.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['it'][435150] = {name = "Mastodonte di Vilferro", additional_info = "1.5 s di lancio\n[q]Evoca e congeda questa cavalcatura.\n[q]\"Questa macchina da guerra è stata rubata da una linea temporale in cui Garrosh Malogrido si è unito alla Legione Infuocata. Diciamo che non è rimasto molto di quella linea temporale.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
