MultiLanguageSpellData['it'][435385] = {name = "[q4]Amuleto dell'Artigianato Terrigeno", additional_info = "2 s di lancio 3\nStrumenti:\nAttrezzi dell'Orefice\nReagenti:\nBlasfemite , Smeraldo Stravagante (8), Pietra Marmorizzata (20), Scintilla (#256)\nReagenti Facoltativi:\nAggiungi abbellimento (#334) , Personalizza statistiche secondarie (#283) , Infondi di potere (#284) , Reagenti Radiosi (#367) , Autenticità dell'Artigiano (#346) , Oltre l'Immaginabile (#384)\nSpecializzazione:\nCreazione di Gioielli - Amuleti\n\n[q4]Amuleto dell'Artigianato Terrigeno\nSi vincola alla raccolta\nCollo\n+9.112 Tempra\n[q2]+ 2.450 Attributo casuale 1\n[q2]+ 2.450 Attributo casuale 2"}
MultiLanguageSpellData['it'][435386] = {name = "[q2]Anello con Sigillo del Concorrente Algari", additional_info = "2 s di lancio 2\nStrumenti:\nAttrezzi dell'Orefice\nReagenti:\nSanguinite Malvagia , Pietra del Nulla , Pietra Marmorizzata (40), Stemma del Concorrente (#255) (3)\nReagenti Facoltativi:\nPersonalizza statistiche secondarie (#283) , Aggiungi abbellimento (#334) , Reagenti Radiosi (#374) , Autenticità dell'Artigiano (#346)\nMercante:\nHotharn\nZona:\nDornogal\nCosto:\n7.500\n\n[q2]Anello con Sigillo del Concorrente Algari\nSi vincola all'equipaggiamento\nDito\n+9.112 Tempra\n[q2]+ 2.450 Attributo casuale 1\n[q2]+ 2.450 Attributo casuale 2\n80"}
