MultiLanguageSpellData['it'][435389] = {name = "[q3]Pietra della Rimembranza", additional_info = "2 s di lancio\nStrumenti:\nAttrezzi dell'Orefice\nReagenti:\nPietra del Nulla (4), Bouquet di Rose Bianche , Bismuto (50), Aqirite (30), Grinfiaferro (30), Pietra Marmorizzata (200)\nMercante:\nLyrendal\nZona:\nDornogal\nCosto:\n150\n\n[q3]Pietra della Rimembranza\nGiocattolo\n[q2]Usa: Offre a un personaggio caduto una degna sepoltura. (5 Min Recupero)\n[q]\"Sempre meglio essere pronti.\""}
MultiLanguageSpellData['it'][435391] = {name = "[q3]Iride dell'Abbellimento", additional_info = "2 s di lancio\nStrumenti:\nAttrezzi dell'Orefice\nReagenti:\nGemme Frantumate (40), Prisma Invertito (5)\nBottino:\nCreature mondiali\n\n[q3]Iride dell'Abbellimento\nGiocattolo\n[q2]Usa: Concentra un raggio di luce colorata attraverso una gemma verso una creatura indifesa. (10 Min Recupero)\n[q]\"Il mondo è crudele. Non dev'essere anche brutto.\""}
