MultiLanguageSpellData['it'][435473] = {name = "Lanterna Inestinguibile", additional_info = "Lanterna Inestinguibile Livello 80\n[q0][Item Effect]Circa 30 apparenze ogni minuto\n[q]Gli incantesimi e le abilità d'attacco a distanza hanno un'alta probabilità di risvegliare la fiamma della lanterna, fornendo un accumulo di Luce di Lampada fino a un massimo di 15 volte.\n\n Dopo 30 s di raccolta di accumuli, la Luce di Lampada si consuma, attirando una quantità equivalente di lucciole che caricano il successivo bersaglio attaccato, esplodendo e infliggendo ( 1 * 82 ) danni da fuoco per lucciola."}
MultiLanguageSpellData['it'][435474] = {name = "Avanti Veloce", additional_info = "Istantaneo\n[q]Increases the caster's attacking and casting speed by 30% for 5 s.\n Increases the movement speed of the caster by 50% for 5 s."}
MultiLanguageSpellData['it'][435475] = {name = "Trappola Abissale", additional_info = "Trappola Abissale Livello 80\n[q0][Item Effect]{Istantaneo} {1 min di recupero}\n[q]Piazza una trappola abissale ai tuoi piedi. Quando un nemico si avvicina a meno di 3 m, si crea una bolla d'acqua gigante per 10 s. Tutti i nemici all'interno della bolla subiscono ( 1 * 105 ) danni da gelo ogni secondo.\n\n La trappola persiste per 1 min prima di venire automaticamente disarmata."}
MultiLanguageSpellData['it'][435476] = {name = "Spiazzamento Temporale", additional_info = "Istantaneo\n[q]Fa sentire disconnessi da questa linea temporale."}
MultiLanguageSpellData['it'][435478] = {name = "Manufatto Esplosivo", additional_info = "Istantaneo\n[q][NYI - Needs trigger] Explode flames outwards in front of you, inflicting 8 Fire damage to any enemy caught in the effect."}
MultiLanguageSpellData['it'][435479] = {name = "Flauto dell'Amico Fungino", additional_info = "Flauto dell'Amico Fungino Livello 80\n[q0][Item Effect]Circa 1 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di dissotterrare un Amico Fungino colorato che cura gli alleati di 2437 , ti rigenera 237 mana o infligge [ 555 * (3)] danni da natura in 3 s a un nemico vicino.\n(1s di recupero)"}
MultiLanguageSpellData['it'][435482] = {name = "Nodo Inanellato di Seta", additional_info = "Nodo Inanellato di Seta Livello 80\n[q0][Item Effect]{Istantaneo} {1 min di recupero}\n[q]Srotola una miriade di ragnatele che intrappolano i nemici frontali, riducendone i danni a te inflitti del 30%, fino a un massimo di 2837 danni totali, e la velocità d'attacco del 15% per 15 s.\n\n [La riduzione della velocità d'attacco è meno efficace contro i nemici di livello superiore a 80.]"}
