MultiLanguageSpellData['it'][435811] = {name = "Micofiore", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il micofiore è un fungo estremamente comune su Khaz Algar. Cresce in qualsiasi luogo e si può trovare praticamente su ogni tipo di terreno."}
MultiLanguageSpellData['it'][435812] = {name = "Micofiore Lussureggiante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il micofiore è un fungo estremamente comune su Khaz Algar. Cresce in qualsiasi luogo e si può trovare praticamente su ogni tipo di terreno.\n\n Alcune erbe crescono rigogliose e prosperano per le più disparate ragioni, a prescindere dal clima o dalla posizione. Gli erbalisti che trovano questi nodi rari possono recuperare reagenti aggiuntivi.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435813] = {name = "Energia Instabile", additional_info = "Portata illimitata\nIstantaneo\n[q]Raccogliere un Frammenti Instabili aumenta le cure fornite e i danni inflitti al Guscio Fortificato del 50% per 30 s. Si accumula.\n\n Inoltre, Energia Instabile infligge 363667 danni da ombra ai personaggi affetti ogni 2 s."}
MultiLanguageSpellData['it'][435814] = {name = "Copertura - Famiglia di Faerin", additional_info = "Portata di 100 m\nIstantaneo\n[q]Curato di recente da te."}
