MultiLanguageSpellData['it'][435817] = {name = "Distruzione Evento", additional_info = nil}
MultiLanguageSpellData['it'][435821] = {name = "Gocciaricca", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Una pianta carnivora che si trova nelle zone sotterranee di Khaz Algar. La gocciaricca sfrutta delle piccole luci bioluminescenti per attirare gli insetti e le altre prede e se ne nutre per prosperare.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435822] = {name = "Orbinide", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Khaz Algar ospita molte specie di piante uniche e l'orbinide è tra queste. Questa pianta sembra in grado di assorbire la magia latente attraverso il suo globo viscoso, che può essere utilizzato in varie professioni, dalla creazione degli inchiostri agli unguenti curativi.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435823] = {name = "Bocciolo della Benedizione", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]I boccioli della benedizione di Khaz Algar possono sembrare innocui a prima vista, ma contengono una pericolosa tossina che può fare estremamente male.\n\n Tuttavia, se maneggiati correttamente, i boccioli della benedizione hanno diverse proprietà medicinali, e un loro infuso è da considerarsi una prelibatezza.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435824] = {name = "Conversazione - Impero di Faerin", additional_info = "Portata di 100 m\nIstantaneo\n[q]Curato di recente da te."}
MultiLanguageSpellData['it'][435825] = {name = "Copertura - Impero di Faerin", additional_info = "Portata di 100 m\nIstantaneo\n[q]Curato di recente da te."}
MultiLanguageSpellData['it'][435826] = {name = "Lancia di Arathor", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Facile da trovare negli spazi luminosi ed esterni di Khaz Algar, la lancia di Arathor è un'erba abbondante con numerosi usi.\n\n Le sue fibre possono essere intrecciate per creare la cartapecora, o strizzate e trattate per ottenere un materiale simile al legno.\n\n Questo consente di usarla per qualsiasi cosa: dai libri, agli archi, ai bastoni.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435829] = {name = "Gocciaricca Lussureggiante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Una pianta carnivora che si trova nelle zone sotterranee di Khaz Algar. La gocciaricca sfrutta delle piccole luci bioluminescenti per attirare gli insetti e le altre prede e se ne nutre per prosperare.\n\n Alcune erbe crescono rigogliose e prosperano per le più disparate ragioni, a prescindere dal clima o dalla posizione. Gli erbalisti che trovano questi nodi rari possono recuperare reagenti aggiuntivi.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435830] = {name = "Orbinide Lussureggiante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Khaz Algar ospita molte specie di piante uniche e l'orbinide è tra queste. Questa pianta sembra in grado di assorbire la magia latente attraverso il suo globo viscoso, che può essere utilizzato in varie professioni, dalla creazione degli inchiostri agli unguenti curativi.\n\n Alcune erbe crescono rigogliose e prosperano per le più disparate ragioni, a prescindere dal clima o dalla posizione. Gli erbalisti che trovano questi nodi rari possono recuperare reagenti aggiuntivi.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435834] = {name = "Bocciolo della Benedizione Lussureggiante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]I boccioli della benedizione di Khaz Algar possono sembrare innocui a prima vista, ma contengono una pericolosa tossina che può fare estremamente male.\n\n Tuttavia, se maneggiati correttamente, i boccioli della benedizione hanno diverse proprietà medicinali, e un loro infuso è da considerarsi una prelibatezza.\n\n Alcune erbe crescono rigogliose e prosperano per le più disparate ragioni, a prescindere dal clima o dalla posizione. Gli erbalisti che trovano questi nodi rari possono recuperare reagenti aggiuntivi.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435836] = {name = "Lancia di Arathor Lussureggiante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Facile da trovare negli spazi luminosi ed esterni di Khaz Algar, la lancia di Arathor è un'erba abbondante con numerosi usi.\n\n Le sue fibre possono essere intrecciate per creare la cartapecora, o strizzate e trattate per ottenere un materiale simile al legno.\n\n Questo consente di usarla per qualsiasi cosa: dai libri, agli archi, ai bastoni.\n\n Alcune erbe crescono rigogliose e prosperano per le più disparate ragioni, a prescindere dal clima o dalla posizione. Gli erbalisti che trovano questi nodi rari possono recuperare reagenti aggiuntivi.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435838] = {name = "Micofiore Cristallizzato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il micofiore è un fungo estremamente comune su Khaz Algar. Cresce in qualsiasi luogo e si può trovare praticamente su ogni tipo di terreno.\n\n A causa della loro vicinanza all'Arteria del Nucleo, alcune erbe hanno un legame diretto con l'Anima del Mondo. Questo collegamento ha provocato una parziale cristallizzazione delle erbe. Se un erbalista vuole raccogliere una di queste erbe, ottiene anche una piccola benedizione oltre a un po' di Polvere Cristallina.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435840] = {name = "Micofiore Alterato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il micofiore è un fungo estremamente comune su Khaz Algar. Cresce in qualsiasi luogo e si può trovare praticamente su ogni tipo di terreno.\n\n Sotto la superficie di Khaz Algar giace il Sangue Nero degli Dei Antichi. Ha iniziato a radunarsi in pozze e la sua corruzione ha avuto un effetto negativo sulla flora locale. Le erbe che hanno avuto la sfortuna di crescere vicino a una tale influenza sono diventate Alterate e... sono più pericolose. Se un erbalista vuole affrontare queste profondità, deve prima affrontare i pericoli della pianta, ottenendo in cambio dei Campioni Informi per i propri sforzi.\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435843] = {name = "Micofiore Irradiato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Il micofiore è un fungo estremamente comune su Khaz Algar. Cresce in qualsiasi luogo e si può trovare praticamente su ogni tipo di terreno.\n\n Gli eventi recenti hanno fatto fuoriuscire dal suolo di Khaz Algar una grande quantità di magia arcana. Come sulle Isole dei Draghi, la flora tende a essere suscettibile alle influenze magiche e questa situazione non è diversa.\n\n Alcune erbe sono diventate Irradiate grazie all'energia arcana. Raccogliere queste erbe permette di ottenere del Residuo di Linea di Faglia, ma ciò che potrebbe accadere con l'energia arcana instabile rimasta è tutta un'altra storia...\nScoperta:\nSi trova da qualche parte a Khaz Algar"}
MultiLanguageSpellData['it'][435845] = {name = "Conversazione - Giochi da Tavolo di Anduin", additional_info = "Portata di 100 m\nIstantaneo\n[q]Curato di recente da te."}
