MultiLanguageSpellData['it'][438608] = {name = "Meteora", additional_info = "Portata di 100 m\nIstantaneo\n[q]Evoca una meteora che cade sulla posizione bersaglio dopo 3 s, infliggendo ([444% of Spell Power]) danni da fuoco a tutti i nemici e brucia il terreno, infliggendo [8 * ([8.53875% of Spell Power])] danni da fuoco in 8.5 s a tutti i nemici nell'area.\n\n Il nemico più vicino al centro del punto d'impatto della meteora subisce il 40% di danni aggiuntivi. Danni ridotti oltre 8 bersagli."}
MultiLanguageSpellData['it'][438609] = {name = "Tempesta di Comete", additional_info = "Portata di 100 m\nIstantaneo\n[q]Evoca una serie di 7 comete ghiacciate sul bersaglio e intorno a esso, ognuna delle quali infligge [7 * ([55% of Spell Power])] danni da gelo a tutti i nemici entro 6 m dal punto d'impatto."}
MultiLanguageSpellData['it'][438611] = {name = "Eccesso di Gelo", additional_info = "Istantaneo\n[q]Fuoco\nConsumare Eccesso di Fuoco fa sì che il successivo lancio di Fiamme della Fenice lanci anche Esplosione di Ghiaccio al 150% dell'efficacia. Questi lanci di Esplosione di Ghiaccio non congelano sul posto i nemici.\n\n Consumare Eccesso di Gelo riduce il tempo di recupero di Meteora di 3 s.\n\nGelo\nConsumare Eccesso di Fuoco fa sì che il successivo lancio di Raffica di Colpi lanci anche Esplosione di Ghiaccio al 150% dell'efficacia. Questi lanci di Esplosione di Ghiaccio non congelano sul posto i nemici.\n\n Consumare Eccesso di Gelo riduce il tempo di recupero di Tempesta di Comete di 3 s.\n(750ms di recupero)"}
