MultiLanguageSpellData['it'][439712] = {name = "Vena di Bismuto", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo molto comune che si trova in tutta Khaz Algar. Nonostante sia comune, è spesso richiesto in grandi quantità dagli artigiani a causa delle sue proprietà versatili.\n\nAnche sotto la superficie, le vene ricche di metallo utilizzabile sono una vista rara ed entusiasmante. Di solito si trovano su muri o sui soffitti negli spazi particolarmente ristretti."}
MultiLanguageSpellData['it'][439713] = {name = "Vena di Aqirite", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo raro che si trova in tutta Khaz Algar, a volte in superficie ma sempre più diffuso man mano che ci si avvicina ad Azj-Kahet. Anche se ha diversi usi, gli ingegneri sono spesso i più interessati a ottenerne grandi quantità.\n\nAnche sotto la superficie, le vene ricche di metallo utilizzabile sono una vista rara ed entusiasmante. Di solito si trovano su muri o sui soffitti negli spazi particolarmente ristretti."}
MultiLanguageSpellData['it'][439714] = {name = "Vena di Grinfiaferro", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo raro che si trova in tutta Khaz Algar, prevalentemente vicino alla superficie o nelle sue vicinanze. È noto per essere estremamente resistente, per cui i fabbri sono spesso interessati a ottenerne grandi quantità.\n\nAnche sotto la superficie, le vene ricche di metallo utilizzabile sono una vista rara ed entusiasmante. Di solito si trovano su muri o sui soffitti negli spazi particolarmente ristretti."}
MultiLanguageSpellData['it'][439715] = {name = "Bismuto Cristallizzato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo molto comune che si trova in tutta Khaz Algar. Nonostante sia comune, è spesso richiesto in grandi quantità dagli artigiani a causa delle sue proprietà versatili.\n\nA causa della loro vicinanza all'Arteria del Nucleo, alcuni depositi hanno sviluppato un legame diretto con l'Anima del Mondo. I minatori che estraggono minerali da questi depositi ricevono una piccola benedizione, oltre a un po' di Polvere Cristallina, reagente utile in molte creazioni."}
MultiLanguageSpellData['it'][439716] = {name = "Aqirite Cristallizzata", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo raro che si trova in tutta Khaz Algar, a volte in superficie ma sempre più diffuso man mano che ci si avvicina ad Azj-Kahet. Anche se ha diversi usi, gli ingegneri sono spesso i più interessati a ottenerne grandi quantità.\n\nA causa della loro vicinanza all'Arteria del Nucleo, alcuni depositi hanno sviluppato un legame diretto con l'Anima del Mondo. I minatori che estraggono minerali da questi depositi ricevono una piccola benedizione, oltre a un po' di Polvere Cristallina, reagente utile in molte creazioni."}
MultiLanguageSpellData['it'][439717] = {name = "Grinfiaferro Cristallizzato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo raro che si trova in tutta Khaz Algar, prevalentemente vicino alla superficie o nelle sue vicinanze. È noto per essere estremamente resistente, per cui i fabbri sono spesso interessati a ottenerne grandi quantità.\n\nA causa della loro vicinanza all'Arteria del Nucleo, alcuni depositi hanno sviluppato un legame diretto con l'Anima del Mondo. I minatori che estraggono minerali da questi depositi ricevono una piccola benedizione, oltre a un po' di Polvere Cristallina, reagente utile in molte creazioni."}
MultiLanguageSpellData['it'][439718] = {name = "Bismuto Piangente", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo molto comune che si trova in tutta Khaz Algar. Nonostante sia comune, è spesso richiesto in grandi quantità dagli artigiani a causa delle sue proprietà versatili.\n\nIl Sangue Nero degli Dei Antichi ha iniziato a creare delle pozze sotto Khaz Algar e la sua presenza contaminante ha avuto degli effetti sui metalli preziosi che ha toccato. I minatori tanto coraggiosi da addentrarsi in profondità per estrarre minerali da questi depositi potrebbero dover affrontare un'agonia insostenibile per un mortale. Ma in caso di sopravvivenza, gli sforzi vengono ripagati con dei Campioni Informi."}
MultiLanguageSpellData['it'][439719] = {name = "Aqirite Piangente", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo raro che si trova in tutta Khaz Algar, a volte in superficie ma sempre più diffuso man mano che ci si avvicina ad Azj-Kahet. Anche se ha diversi usi, gli ingegneri sono spesso i più interessati a ottenerne grandi quantità.\n\nIl Sangue Nero degli Dei Antichi ha iniziato a creare delle pozze sotto Khaz Algar e la sua presenza contaminante ha avuto degli effetti sui metalli preziosi che ha toccato. I minatori tanto coraggiosi da addentrarsi in profondità per estrarre minerali da questi depositi potrebbero dover affrontare un'agonia insostenibile per un mortale. Ma in caso di sopravvivenza, gli sforzi vengono ripagati con dei Campioni Informi."}
MultiLanguageSpellData['it'][439720] = {name = "Grinfiaferro Piangente", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo raro che si trova in tutta Khaz Algar, prevalentemente vicino alla superficie o nelle sue vicinanze. È noto per essere estremamente resistente, per cui i fabbri sono spesso interessati a ottenerne grandi quantità.\n\nIl Sangue Nero degli Dei Antichi ha iniziato a creare delle pozze sotto Khaz Algar e la sua presenza contaminante ha avuto degli effetti sui metalli preziosi che ha toccato. I minatori tanto coraggiosi da addentrarsi in profondità per estrarre minerali da questi depositi potrebbero dover affrontare un'agonia insostenibile per un mortale. Ma in caso di sopravvivenza, gli sforzi vengono ripagati con dei Campioni Informi."}
MultiLanguageSpellData['it'][439721] = {name = "Bismuto Esplosivo", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un metallo molto comune che si trova in tutta Khaz Algar. Nonostante sia comune, è spesso richiesto in grandi quantità dagli artigiani a causa delle sue proprietà versatili.\n\nLa natura opera in modi misteriosi, ma non c'è niente di naturale sulle rocce ricoperte di dinamite! I depositi ricchi di metalli individuati da \"volenterosi\" ingegneri vengono talvolta predisposti per una detonazione, per un'estrazione più facile, ma spesso vengono abbandonati quando il demolitore torna in sé.\n\n Mantenere la distanza e scavare con attenzione potrebbe essere sufficiente per estrarre un paio di pezzi. Il processo della selezione naturale non richiede ulteriori spiegazioni.\n\n Buona fortuna!"}
