MultiLanguageSpellData['it'][439742] = {name = "Sovraccarico Cristallizzato", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Sovraccaricare un deposito Cristallizzato sintonizza temporaneamente con il mondo, creando un portale che invia su un altro deposito vicino. I minatori specializzati, una volta estratto il minerale sulla destinazione, possono aprire un portale per tornare al punto di origine."}
MultiLanguageSpellData['it'][439743] = {name = "Sovraccarico Piangente", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Sovraccaricare un deposito Piangente provoca una mutazione immediata che lo trasforma in una creatura pericolosa. Tale creatura può fornire una fonte sana di Campioni Informi."}
MultiLanguageSpellData['it'][439744] = {name = "Sovraccarico Esplosivo", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Sovraccaricare depositi minerari ricoperti di dinamite sembra una decisione sciocca e confusa, ma è una pratica sempre più popolare ora che i depositi minerari armati vengono via via abbandonati. I minatori sufficientemente imprudenti possono sovraccaricare il deposito e hanno quindi pochi secondi a disposizione per raccogliere dei minerali aggiuntivi e per riflettere su tutte le scelte che hanno portato a quella decisione."}
MultiLanguageSpellData['it'][439746] = {name = "Ombra Echeggiante", additional_info = "Portata di 100 m\nIstantaneo\n[q]Le ombre di Nx riecheggiano la sua Lacerazione dell'Ombra nella direzione verso cui sono rivolte."}
MultiLanguageSpellData['it'][439747] = {name = "Sovraccarico Depositi Avvolti da Ragnatele", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]I Ragni del Fuso hanno la tendenza ad annidarsi tra i robusti affioramenti rocciosi. La maggior parte dei minatori preferisce estrarre ciò che può senza disturbarli, ma sovraccaricare un Deposito Avvolto da Ragnatele può agitarli e farli scappare. E catturare questi Ragni del Fuso è un'ottima fonte di stoffe aggiuntive!"}
