MultiLanguageSpellData['it'][440042] = {name = "Oscuramento Anima", additional_info = "[q]Demonologia, Distruzione\n I danni periodici inflitti da Immolazione hanno una probabilità di infliggere al bersaglio ([46.9878% of Spell Power]) danni da ombrofuoco in 15 s.\n\n I danni inflitti da Dardo del Caos consumano Oscuramento Anima, infliggendo istantaneamente i danni restanti. I danni inflitti da Pioggia di Fuoco consumano 1 s di Oscuramento Anima.\n\nAfflizione\n I danni periodici inflitti da Corruzione hanno una probabilità di infliggere al bersaglio ([46.9878% of Spell Power]) danni da ombrofuoco in 15 s.\n\n I danni inflitti da Estasi Malefica consumano Oscuramento Anima, infliggendo istantaneamente i danni restanti."}
MultiLanguageSpellData['it'][440043] = {name = "Anima Annerita", additional_info = "[q]Consumare frammenti d'anima con gli incantesimi d'attacco corrompe i nemici affetti da Avvizzimento, aumentandone gli accumuli di 1.\n\n Ogni volta che gli accumuli di Avvizzimento aumentano, l'effetto ha una probabilità di collassare, consumando un accumulo ogni 1 s e infliggendo ([76.6411% of Spell Power]) danni da ombrofuoco al suo ospite finché non rimane 1 accumulo."}
MultiLanguageSpellData['it'][440044] = {name = "Ferocia di Xalan", additional_info = "[q]Afflizione\n Aumenta i danni da fuoco inflitti da incantesimi e abilità del 6% e aumenta la probabilità di critico fornita da tutte le fonti agli incantesimi di fuoco del 10%.\n\nDistruzione\n Aumenta i danni da fuoco inflitti da incantesimi e abilità del 8% e aumenta la probabilità di critico fornita da tutte le fonti agli incantesimi di fuoco del 10%."}
MultiLanguageSpellData['it'][440045] = {name = "Marchio di Peroth'arn", additional_info = "[q]Distruzione\n Aumenta i danni critici inflitti da Avvizzimento del 10%.\n\n Avvizzimento ha una probabilità di ottenere un accumulo quando infligge danni critici. Gli accumuli ottenuti in questo modo non attivano Anima Annerita.\n\nAfflizione\n Aumenta i danni critici inflitti da Avvizzimento del 25%.\n\n Avvizzimento ha una probabilità di ottenere un accumulo quando infligge danni critici. Gli accumuli ottenuti in questo modo non attivano Anima Annerita."}
MultiLanguageSpellData['it'][440046] = {name = "Marchio di Xavius", additional_info = "[q][ Agonia : Aumenta i danni inflitti da Agonia del 20% / Aumenta i danni inflitti da Avvizzimento del 25%.]\n Anima Annerita infligge il 2% di danni aggiuntivi per ogni accumulo di Avvizzimento."}
MultiLanguageSpellData['it'][440047] = {name = "Attività Risvegliata Settimanale", additional_info = "Istantaneo\n[q]Completare questa missione fornisce una scintilla settimanale per l'artigianato.\n\nQuesta settimana hai già ricevuto la tua scintilla settimanale per l'artigianato."}
MultiLanguageSpellData['it'][440048] = {name = "Rituali dei Furiatorva", additional_info = "[q]Aumenta i danni periodici inflitti da Avvizzimento del 30% ma ne riduce la durata del 15%."}
MultiLanguageSpellData['it'][440049] = {name = "Passo Sinergico", additional_info = "Portata di 100 m\nIstantaneo\n[q]Quando raggiungono 100 energia, Nx e Vx scattano ripetutamente nell'arena, infliggendo 1939560 danni fisici ai personaggi sulla traiettoria. Quindi, invertono i loro ruoli d'attacco e di supporto."}
MultiLanguageSpellData['it'][440051] = {name = "Strategie dei Cuorcupo", additional_info = "[q]Aumenta i danni inflitti da Avvizzimento del 20%. Quando Avvizzimento ottiene un accumulo da Anima Annerita, ha una probabilità di ottenere un accumulo aggiuntivo."}
MultiLanguageSpellData['it'][440055] = {name = "Semi della Disfatta", additional_info = "[q]Distruzione\n Quando Avvizzimento raggiunge 8 accumuli o il suo ospite raggiunge il 20% della salute massima, Avvizzimento infligge ([76.6411% of Spell Power]) danni da ombrofuoco al suo ospite ogni 1 s finché non resta 1 solo accumulo.\n\n I danni inflitti da Anima Annerita hanno una probabilità di fornire 2 accumulo di Punto di Rottura.\n\nAfflizione\n Quando Avvizzimento raggiunge 8 accumuli o il suo ospite raggiunge il 20% della salute massima, Avvizzimento infligge ([76.6411% of Spell Power]) danni da ombrofuoco al suo ospite ogni 1 s finché non resta 1 solo accumulo.\n\n I danni inflitti da Anima Annerita hanno una probabilità di fornire Crescendo Tormentato."}
