MultiLanguageSpellData['it'][442566] = {name = "Chitina di Tenebre", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Un'ampia varietà di insetti a Khaz Algar si è dotata di armature più robuste, simili a esoscheletri chitinosi, invece delle semplici scaglie."}
MultiLanguageSpellData['it'][442567] = {name = "Cuoio Caricato dalla Tempesta", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]È possibile trovare una serie di creature in tutta Khaz Algar. Il cuoio raccolto da loro può essere usato per creare diversi beni, armature e altri reagenti."}
MultiLanguageSpellData['it'][442569] = {name = "Carapace Senzasole", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Scuoiare le creature ricoperte di chitina fornisce una piccola probabilità di trovare del Carapace Senzasole.\n\n Questo materiale è più resistente e completo della chitina e può essere usato per i pezzi più difficili."}
MultiLanguageSpellData['it'][442572] = {name = "Pelle Tonante", additional_info = "Portata di 5 m\n2.5 s di lancio\n[q]Scuoiare le creature ricoperte di pelle fornisce una piccola probabilità di trovare della Pelle Tonante.\n\n Questo materiale estremamente raro è adatto a progetti di ogni genere per diverse professioni."}
MultiLanguageSpellData['it'][442573] = {name = "Assassinio", additional_info = "Portata illimitata\nIstantaneo\n[q]L'Eterea marchia a morte diversi personaggi. Dopo 8 s, l'Eterea si sposta furtivamente verso ogni bersaglio e lo eviscera, infliggendo 4605052 danni da ombra entro 5 m e iniettando Rovina della Regina.\n\n La figura d'ombra dell'Etereo risuona, creando un Fantasma Fatuo su ogni posizione."}
