MultiLanguageSpellData['it'][442644] = {name = "[q2]Esca per Pesce Arcobaleno Speculare", additional_info = "2 s di lancio\nReagenti:\nLeucisco Procrastinatore (2)\nSpecializzazione:\nRaccolta - Pesca nel Sangue\n\n[q2]Esca per Pesce Arcobaleno Speculare\n[q2]Usa: Aumenta la probabilità di pescare un Pesce Arcobaleno Speculare per 30 min.\n70"}
MultiLanguageSpellData['it'][442645] = {name = "[q2]Esca per Spigola di Fiume Quieta", additional_info = "2 s di lancio\nReagenti:\nPersico Cruento (2)\nSpecializzazione:\nRaccolta - Pesca nel Sangue (10)\n\n[q2]Esca per Spigola di Fiume Quieta\n[q2]Usa: Aumenta la probabilità di pescare una Spigola di Fiume Quieta per 30 min.\n70"}
MultiLanguageSpellData['it'][442646] = {name = "[q2]Esca per Luccio di Dorn", additional_info = "2 s di lancio\nReagenti:\nStorione Cristallino (2)\nSpecializzazione:\nRaccolta - Pesca nel Sangue (20)\n\n[q2]Esca per Luccio di Dorn\n[q2]Usa: Aumenta la probabilità di pescare un Luccio di Dorn per 30 min.\n70"}
MultiLanguageSpellData['it'][442647] = {name = "[q2]Esca per Pesce Martello di Arathor", additional_info = "2 s di lancio\nReagenti:\nRodeo di Bismuto (2)\nSpecializzazione:\nRaccolta - Pesca nel Sangue (30)\n\n[q2]Esca per Pesce Martello di Arathor\n[q2]Usa: Aumenta la probabilità di pescare un Pesce Martello di Arathor per 30 min.\n70"}
MultiLanguageSpellData['it'][442648] = {name = "[q2]Esca per Grandocchio Ruggente", additional_info = "2 s di lancio\nReagenti:\nLeucisco Procrastinatore , Persico Cruento , Storione Cristallino , Rodeo di Bismuto\nSpecializzazione:\nRaccolta - Pesca nel Sangue (40)\n\n[q2]Esca per Grandocchio Ruggente\n[q2]Usa: Mette sull'amo un'esca per Grandocchio, garantendo di pescarne dalle Pozze di Pesca delle Profondità Risonanti e dei Precipizi Sacri.\n\n L'esca dura 30 min e si accumula fino a 50 volte.\n70"}
MultiLanguageSpellData['it'][442649] = {name = "[q3]Infusione: Cristallo", additional_info = "2 s di lancio\nReagenti:\nEsca per Creature Elusive , Polvere Cristallina (3)\nSpecializzazione:\nEsche - Instillatore Notevole\n\n[q3]Esca per Creature Cristallina\nSi vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\n70\n[q]\"Un'esca allettante che attira allo scoperto le creature più elusive. Infusa di potere cristallino.\""}
MultiLanguageSpellData['it'][442650] = {name = "[q3]Infusione: Spore", additional_info = "2 s di lancio\nReagenti:\nEsca per Creature Elusive , Spore Viridescenti (3)\nSpecializzazione:\nEsche - Instillatore Notevole (20)\n\n[q3]Esca per Creature Infusa di Spore\nSi vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\n70\n[q]\"Un'esca allettante che attira allo scoperto le creature più elusive. Infusa di spore magiche.\""}
MultiLanguageSpellData['it'][442651] = {name = "[q3]Infusione: Informe", additional_info = "2 s di lancio\nReagenti:\nEsca per Creature Elusive , Campione Informe\nSpecializzazione:\nEsche - Instillatore Notevole (40)\n\n[q3]Esca per Creature Informe\nSi vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\n70\n[q]\"Un'esca allettante che attira allo scoperto le creature più elusive. Infusa di un'essenza che trasuda un'energia malvagia.\""}
MultiLanguageSpellData['it'][442652] = {name = "[q2]Esca per Creature Elusive", additional_info = "2 s di lancio\nReagenti:\nFiletto Base (10)\nSpecializzazione:\nEsche\n\n[q2]Esca per Creature Elusive\nSi vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\n70\nRichiedeScuoiatura di Khaz Algar\n(1)\n[q]\"Un'esca che attira le creature più sfuggenti.\""}
