MultiLanguageSpellData['it'][442799] = {name = "Inondazione di Sangue", additional_info = "Portata di 300 m\nIstantaneo\n[q]Il contenitore di Sangue Nero perde il contenuto sul pavimento della camera, creando una pozza che cresce lentamente nel tempo. La pozza infligge 287816 danni da ombra e assorbe le successive 490734 cure ricevute ogni 0.5 s dai personaggi nell'area d'effetto.\n\n Le Uova Sperimentali che entrano in contatto con la pozza attivano Reazione Caustica ."}
MultiLanguageSpellData['it'][442801] = {name = "Miccia di Fuocobrado", additional_info = "Portata di 50 m\nIstantaneo\n[q]Gli attacchi in mischia hanno una probabilità di incendiare il bersaglio, infliggendo ( 53 * 11) danni da fuoco in 11 s.\n\n Attivare questo effetto quando il bersaglio è già incendiato ne rinnova la durata, diffondendolo anche su un nemico vicino."}
MultiLanguageSpellData['it'][442802] = {name = "Inondazione di Sangue", additional_info = "Portata di 300 m\nIstantaneo\n[q]Inondazione di Sangue fa schiudere ogni nuovo che tocca e fa mutare la creatura all'interno."}
MultiLanguageSpellData['it'][442804] = {name = "Maledizione del Satiro", additional_info = "{1% della base mana} {Portata di 40 m}\nIstantaneo\n[q]Aumenta l'intervallo tra gli attacchi di un nemico del 20% e il tempo di lancio di tutti gli incantesimi del 30% per 2 min.\n\nMaledizioni: uno Stregone può avere solo una maledizione attiva su ogni bersaglio."}
