MultiLanguageSpellData['it'][443445] = {name = "Comunicazione Costante", additional_info = "[q]Elementale\n I lanci di Dardo Fulminante, Getto di Lava, Catena di Fulmini, Furiagelida e Folgore del Gelo hanno una probabilità del 8% di richiamare un Antenato al tuo fianco per 6 s.\n\nRigenerazione\n Marea Benefica ha una probabilità del 15% di richiamare un Antenato al tuo fianco per 6 s."}
MultiLanguageSpellData['it'][443446] = {name = "Ultima Chiamata", additional_info = "[q]Elementale\n Quando svanisce, l'Antenato lancia Detonazione Elementale su un nemico vicino.\n\nRigenerazione\n Quando svanisce, l'Antenato lancia Idrobolla su un alleato ferito vicino.\n\n Idrobolla\nCirconda il bersaglio in uno scudo d'acqua protettivo per 15 s.\n\n Lo scudo assorbe i successivi 0 danni subiti, ma la quantità assorbita decade nel corso della sua durata."}
MultiLanguageSpellData['it'][443447] = {name = "Supremazia del Maelstrom", additional_info = "[q]Elementale\n Aumenta i danni inflitti da Folgore della Terra, Detonazione Elementale e Terremoto del 25%.\n\n Aumenta le cure fornite da Eruzione Benefica e Catena di Guarigione del 25%.\n\nRigenerazione\n Aumenta le cure fornite da Ondata di Cura, Eruzione Benefica, Fonte, Nubifragio e Catena di Guarigione del 25%."}
MultiLanguageSpellData['it'][443448] = {name = "Capacità Primordiale", additional_info = "[q]Elementale\n Aumenta il maelstrom massimo di 25.\n\nRigenerazione\n Aumenta il mana massimo del 10%.\n\n Onde di Marea può accumularsi fino a 4 volte."}
MultiLanguageSpellData['it'][443449] = {name = "Saggezza Latente", additional_info = "[q]Aumenta la potenza degli incantesimi degli Antenati del 25%."}
MultiLanguageSpellData['it'][443450] = {name = "Chiamata Ancestrale", additional_info = "[q]Rigenerazione\n Beneficiare di Ondeggiamento richiama un Antenato al tuo fianco per 6 s.\n\n Lanciare Scarica della Vita richiama un Antenato al tuo fianco per 12 s.\n\n Quando si lancia un incantesimo d'attacco o di cura, l'Antenato ne lancia uno simile.\n\nElementale\n Ondata Primordiale richiama un Antenato al tuo fianco per 6 s. Quando si lancia un incantesimo d'attacco o di cura, l'Antenato ne lancia uno simile."}
MultiLanguageSpellData['it'][443451] = {name = "Offerta dall'Aldilà", additional_info = "[q]Elementale\n Quando viene richiamato un Antenato, riduce il tempo di recupero di Elementale del Fuoco ed Elementale della Tempesta di 5 s.\n\nRigenerazione\n Quando viene richiamato un Antenato, riduce il tempo di recupero di Marea Benefica di 3 s."}
