MultiLanguageSpellData['it'][443525] = {name = "Fischietto del Portatore di Candela", additional_info = "Fischietto del Portatore di Candela Livello 80\n[q0][Item Effect]Circa 1.5 apparenze ogni minuto\n[q]Gli attacchi hanno una probabilità di dirigere un carretto dei Coboldi verso il bersaglio, inviando una truppa che si scontra con i nemici e infligge ( 1 * 1547 ) danni fisici suddivisi tra i nemici colpiti."}
MultiLanguageSpellData['it'][443526] = {name = "Premonizione di Conforto", additional_info = "Portata di 100 m\nIstantaneo\n[q]Il successivo incantesimo di cura a bersaglio singolo fornisce uno scudo che assorbe 0 danni subiti e riduce i danni subiti dal bersaglio del 15% per 15 s."}
MultiLanguageSpellData['it'][443527] = {name = "Cera di Ardikon Intagliata", additional_info = "Cera di Ardikon Intagliata Livello 80\n[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Gli incantesimi hanno una probabilità di infondere la cera, trasformandola in una candela fiammeggiante che aumenta l'indice di versatilità di 122 per 15 s, ulteriormente aumentato di 32 finché si rimane all'interno della luce."}
