MultiLanguageSpellData['it'][443529] = {name = "Bulino del Re delle Candele", additional_info = "Bulino del Re delle Candele Livello 80\n[q0][Item Effect]Portata di 40 m\n{Istantaneo} {1.5 min di recupero}\n[q]Intaglia una copia di cera del bersaglio, che assorbe il 50% dei danni subiti. L'assorbimento scalda la cera, che si scioglie dopo aver assorbito 6705 danni."}
MultiLanguageSpellData['it'][443530] = {name = "Residuo di Tenebra", additional_info = "Residuo di Tenebra Livello 80\n[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Le abilità hanno una probabilità di richiamare l'Oscurità, aumentando [[Primary Stat]] di 19 , fino a un massimo di ( 19 * 5).\n\n Quando raggiunge il pieno potere, l'Oscurità si scatena, infliggendo ( 1 * 1789 * 15 / 3) danni da ombra suddivisi tra i nemici vicini in 15 s prima di tornare a essere un residuo."}
MultiLanguageSpellData['it'][443531] = {name = "Luce di Rinforzo", additional_info = "Luce di Rinforzo Livello 80\n[q0][Item Effect]{Istantaneo} {2 min di recupero}\n[q]Alza l'anello con sigillo verso la Luce, aumentando la statistica secondaria più alta di 260 per 20 s. Il gesto ispira tutti i membri del gruppo vicini che hanno un anello con sigillo, fornendo loro 7 della stessa statistica per 20 s."}
MultiLanguageSpellData['it'][443532] = {name = "Vincolo Oscuro", additional_info = "Istantaneo\n[q][ Sangue : Ebollizione del Sangue infligge il 10% di danni aggiuntivi /\n\nGelo\nLa Folata Gelida potenziata da Brina infligge il 60% di danni aggiuntivi contro il bersaglio principale ] e ora infligge danni da ombrogelo.\n\n I danni da ombrogelo applicano 2 accumuli di Marchio della Mietitrice e 4 accumuli in caso di colpo critico."}
MultiLanguageSpellData['it'][443533] = {name = "Tomo della Devozione alla Luce", additional_info = "Tomo della Devozione alla Luce Livello 80\n[q0][Item Effect][q]Avanza ai 50 Versi di Resilienza Interiore, leggendoli mentre ti attaccano.\n Resilienza Interiore aumenta l'armatura di 136 e fornisce agli attacchi una probabilità di invocare uno scudo che assorbe 3376 danni magici subiti. Al termine, si passa a leggere un altro capitolo.\n\nValido solo per le specializzazioni da difensore.\n(500ms di recupero)"}
MultiLanguageSpellData['it'][443534] = {name = "Radiosità", additional_info = "Istantaneo\n[q]La radiosità aumenta l'efficacia del Verso."}
MultiLanguageSpellData['it'][443535] = {name = "Tomo della Devozione alla Luce", additional_info = "[q0][Item Effect]{Istantaneo} {1.5 min di recupero}\n[q]Permette di sfogliare i passaggi nel tomo con maggiore Radiosità ."}
MultiLanguageSpellData['it'][443536] = {name = "Scheggialuce Esplosiva", additional_info = "Scheggialuce Esplosiva Livello 80\n[q0][Item Effect]Portata di 35 m\n{Istantaneo} {2 min di recupero}\n[q]Evoca un esemplare di Prole della Luce Ribollente che sacrifica la sua salute per scatenare Esplosioni di Luce, infliggendo 1446 danni da sacro suddivisi tra i nemici vicini ogni 2 s finché è vivo."}
MultiLanguageSpellData['it'][443537] = {name = "Pietra del Patto del Vuoto", additional_info = "Pietra del Patto del Vuoto Livello 80\n[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Gli attacchi hanno una probabilità di evocare il patto, infliggendo ( 1 * 897 ) danni da ombra suddivisi tra i nemici vicini e aumentando l'indice di celerità di 36 per 10 s.\n\n La tua morte annulla il patto, provocando una violenta esplosione."}
MultiLanguageSpellData['it'][443538] = {name = "Cristallo Potenziante di Anub'ikkaj", additional_info = "Cristallo Potenziante di Anub'ikkaj Livello 80\n[q0][Item Effect]Circa 1.55 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di rilasciare un potenziamento crescente dal cristallo, aumentando una statistica secondaria casuale di 131 per 20 s."}
MultiLanguageSpellData['it'][443539] = {name = "Rintocco di Mereldar", additional_info = "[q0][Item Effect]Portata di 50 m\nIstantaneo\n[q]Rilascia un rintocco di luce sacra sul bersaglio, infliggendo ( 1 * 1368 ) danni da sacro. I successivi 5 alleati che attaccano il bersaglio ricevono la Benedizione di Mereldar, che ne aumenta l'indice di versatilità di 62 per 10 s."}
MultiLanguageSpellData['it'][443541] = {name = "Sacca della Stirpe di Ara-Kara", additional_info = "Sacca della Stirpe di Ara-Kara Livello 80\n[q0][Item Effect]Circa 2.5 apparenze ogni minuto\n[q]Le abilità hanno una probabilità di agitare la sacca, rilasciando un uovo che fornisce 15 [[Primary Stat]]. Ogni uovo si schiude dopo 1 min e la nuova stirpe attacca il bersaglio successivo, infliggendo ( 1 * 80 * 8 / 1) danni da natura in 8 s.\n(100ms di recupero)"}
MultiLanguageSpellData['it'][443544] = {name = "Modulo d'Aggressione Rifrangente", additional_info = "Modulo d'Aggressione Rifrangente Livello 80\n[q0][Item Effect][q]Le abilità di provocazione attivano l'energia rifrangente del modulo, proteggendoti dal 50% dei danni subiti, fino a un massimo di 7648 . Può verificarsi solo una volta ogni 1 min.\n\nValido solo per le specializzazioni da difensore.\n(1m di recupero)"}
MultiLanguageSpellData['it'][443545] = {name = "Ghiandola di Sciame Incessante", additional_info = "Ghiandola di Sciame Incessante Livello 80\n[q0][Item Effect]Circa 6 apparenze ogni minuto\n[q]La ghiandola rilascia feromoni che attraggono uno Sciame Incessante di insetti tutt'intorno. Subire danni fornisce un'alta probabilità di contrattaccare gli attaccanti, infliggendo ( 69 * 6 / 1) danni da natura in 6 s e riducendo i danni subiti di 96 ."}
MultiLanguageSpellData['it'][443549] = {name = "Editto del Mietitore", additional_info = "[q0][Item Effect]Portata di 100 m\nIstantaneo\n[q]Gli incantesimi e le abilità d'attacco hanno una probabilità di lanciare un globo di Sangue Nero instabile verso il bersaglio. All'impatto, il globo esplode, infliggendo ( 1 * 1418 ) danni da ombra suddivisi tra tutti i nemici vicini. Intercettare il lancio permette di assorbirne il potere, aumentando l'indice di maestria di 156 per 15 s."}
MultiLanguageSpellData['it'][443552] = {name = "Orazione Opprimente", additional_info = "Orazione Opprimente Livello 80\n[q0][Item Effect]{Istantaneo} {2 min di recupero}\n[q]Sventola la laringe in aria per scatenare un coro di tormenti, che infligge ( 1 * 1480 * 3 / 1) danni da ombra in 3 s suddivisi tra i nemici vicini. I sussurri se ne vanno per unirsi al coro, aumentandone i danni subiti prima di diventare silenti."}
MultiLanguageSpellData['it'][443553] = {name = "Respinta della Carica dell'Alce", additional_info = "Portata illimitata\nIstantaneo\n[q]Carica il bersaglio, dandogli una testata e respingendolo indietro."}
MultiLanguageSpellData['it'][443556] = {name = "Strumenti delle Zanne Gemelle", additional_info = "Strumenti delle Zanne Gemelle Livello 80\n[q0][Item Effect]{Istantaneo} {2 min di recupero}\n[q]Apre la borsa per tirarne fuori una delle lame di Nx e colpire rapidamente i nemici frontali, infliggendo ( 1 * 585 ) danni da ombra a tutti i nemici colpiti.\n\n È possibile usare la borsa fino a 2 volte aggiuntive entro 20 s, prima che si sigilli per ricaricare magicamente il contenuto."}
MultiLanguageSpellData['it'][443557] = {name = "Amalgama Coagulato Viscoso", additional_info = "Amalgama Coagulato Viscoso Livello 80\n[q0][Item Effect][q]Le sovracure attraggono l'energia dell'ombra nelle vicinanze, accumulando fino a 213 cure e rigenerando la salute del bersaglio quando subisce danni."}
MultiLanguageSpellData['it'][443558] = {name = "Membrana Coagulata", additional_info = "[q0][Item Effect]Portata di 46 m\n{Istantaneo} {1 min di recupero}\n[q]Canalizza il potere dell'Amalgama Coagulato, dirigendo tutta l'energia d'ombra attuale per proteggere il bersaglio."}
MultiLanguageSpellData['it'][443559] = {name = "Mistura Cirrale", additional_info = "[q0][Item Effect]Circa 2 apparenze ogni minuto\n[q]Gli incantesimi hanno una probabilità di ispirare a sperimentare su un alleato, potenziandolo in modi imprevisti per 20 s."}
MultiLanguageSpellData['it'][443560] = {name = "Rapido e Doloroso", additional_info = "[q]Sangue\n Se Perforazione dell'Anima non colpisce nemici, aumenta la Forza del 10% per 8 s.\n\n Aumenta del 100% l'efficacia di Ondata di Anime sul bersaglio principale di Marchio della Mietitrice.\n\nGelo\n Se Perforazione dell'Anima non colpisce nemici, aumenta la Forza del 5% per 8 s.\n\n Aumenta del 50% l'efficacia di Ondata di Anime sul bersaglio principale di Marchio della Mietitrice."}
