MultiLanguageSpellData['it'][444062] = {name = "Saluto", additional_info = "Istantaneo\n[q]Saluta gli altri Terrigeni, assicurando loro che il viaggio di ritorno sarà sicuro."}
MultiLanguageSpellData['it'][444066] = {name = "Teletrasporto", additional_info = "5 s di lancio\n[q]La ologemma permette di teletrasportarsi verso un'altra posizione."}
MultiLanguageSpellData['it'][444067] = {name = "Contratto della Mietitrice del Vuoto", additional_info = "Contratto della Mietitrice del Vuoto Livello 80\n[q0][Item Effect]Circa 3 apparenze ogni minuto\n[q]Le abilità hanno un'alta probabilità di evocare un fantasma etereo, infliggendo ( 1 * 600 ) danni da ombra al bersaglio e [ 1 * 600 * (0.09)] danni da ombra a tutti gli altri nemici colpiti sulla traiettoria.\n\n Se il bersaglio ha meno del 35% della salute massima, l'effetto evoca due fantasmi aggiuntivi al 25% dell'efficacia.\n(1s di recupero)"}
MultiLanguageSpellData['it'][444068] = {name = "[q4]Avambracci dell'Oscurità Crescente", additional_info = "2 s di lancio 3\nReagenti:\nFiala di Oli dei Kaheti (2), Chitina di Sciame Kaheti (10), Pelle Irrequieta (2), Legatura d'Armatura di Chitina , Scintilla (#256)\nReagenti Facoltativi:\nInfondi di potere (#284) , Armature di Maglia (#287) , Autenticità dell'Artigiano (#346) , Oltre l'Immaginabile (#384)\nBottino:\nCreature mondiali\n\n[q4]Avambracci dell'Oscurità Crescente\nSi vincola alla raccolta\nPolsi Maglia\n2317 Armatura\n+1.198 [Agilità o Intelletto]+5.483 Tempra\n[q2]+ 351 Versatilità\n[q2]+ 468 Maestria\nIntegrità 55 / 55\n[q2]Equipaggia: Infliggere danni fornisce una probabilità di ottenere 1 accumulo di Oscurità Crescente. Al raggiungimento di 5 accumuli, l'Oscurità esplode, infliggendo ( 1 * 161232 ) danni da ombra suddivisi tra tutti i nemici vicini. I danni aumentano per ogni bersaglio, fino a un massimo di 5. Successivamente, le ombre ti appesantiscono e riducono la velocità di movimento del 15% per 5 s.\n\n È un abbellimento Nerubiano.\n80"}
MultiLanguageSpellData['it'][444069] = {name = "Furia dei Cavalieri", additional_info = "[q]Ogni 50 potenza runica consumata, estende la durata dell'aiuto fornito dai Cavalieri in combattimento di 1 s, fino a un massimo di 5 s."}
MultiLanguageSpellData['it'][444070] = {name = "[q4]Fibbia dell'Impeto Adrenalinico", additional_info = "2 s di lancio 3\nReagenti:\nFiala di Oli dei Kaheti (2), Chitina di Sciame Kaheti (10), Pelle Irrequieta (2), Legatura d'Armatura di Chitina , Scintilla (#256)\nReagenti Facoltativi:\nInfondi di potere (#284) , Armature di Cuoio (#286) , Autenticità dell'Artigiano (#346) , Oltre l'Immaginabile (#384)\nBottino:\nSikran, Capitano dei Sureki\nZona:\nPalazzo dei Nerub'ar\nRicetta:\nAcquistabile alla Casa d'Aste\n\n[q4]Fibbia dell'Impeto Adrenalinico\nSi vincola alla raccolta\nFianchi Cuoio\n1767 Armatura\n+1.597 [Agilità o Intelletto]+7.311 Tempra\n[q2]+ 624 Critico\n[q2]+ 468 Versatilità\nIntegrità 55 / 55\n[q2]Equipaggia: Subire danni fornisce una probabilità di attivare Impeto Adrenalinico, che aumenta [[Primary Stat]] di 1265 e riduce l'indice di maestria di 207 per 12 s.\n\n È un abbellimento Nerubiano. (15s di recupero)\n80"}
MultiLanguageSpellData['it'][444071] = {name = "[q4]Stivaloni della Fiamma Unificatrice", additional_info = "2 s di lancio 3\nReagenti:\nAccendifiamma Profanato (2), Cuoio Caricato dalla Tempesta (150), Pelle Infusa di Cristalli (3), Legatura d'Armatura di Chitina , Scintilla (#256)\nReagenti Facoltativi:\nInfondi di potere (#284) , Armature di Cuoio (#286) , Autenticità dell'Artigiano (#346) , Oltre l'Immaginabile (#384)\nBottino:\nPriora Fedecerda\nZona:\nPrioria della Fiamma Sacra\n\n[q4]Stivaloni della Fiamma Unificatrice\nSi vincola alla raccolta\nPiedi Cuoio\n1964 Armatura\n+1.597 [Agilità o Intelletto]+7.311 Tempra\n[q2]+ 624 Celerità\n[q2]+ 468 Maestria\nIntegrità 80 / 80\n[q2]Equipaggia: Curare un alleato fornisce una probabilità che entrambi otteniate Brace Unificatrice. Quando due Braci Unificatrici entrano in contatto tra loro, esplodono in Fiamme Unificatrici.\n\n L'effetto di Fiamme Unificatrici aumenta la statistica secondaria più alta di 1175 e una statistica secondaria casuale di 235 .\n80"}
MultiLanguageSpellData['it'][444072] = {name = "Banchetto di Anime", additional_info = "[q]Quando ci sono almeno 2 Cavalieri in aiuto, le abilità che consumano potenza runica infliggono il 20% di danni aggiuntivi."}
MultiLanguageSpellData['it'][444073] = {name = "[q4]Paramani del Portatore della Torcia Benedetto", additional_info = "2 s di lancio 3\nReagenti:\nAccendifiamma Profanato (3), Chitina di Tenebre (150), Pelle Infusa di Cristalli (3), Legatura d'Armatura di Chitina , Scintilla (#256)\nReagenti Facoltativi:\nInfondi di potere (#284) , Armature di Maglia (#287) , Autenticità dell'Artigiano (#346) , Oltre l'Immaginabile (#384)\nMissione:\nDiffondere la Luce\n\n[q4]Paramani del Portatore della Torcia Benedetto\nSi vincola alla raccolta\nMani Maglia\n2606 Armatura\n+1.597 [Agilità o Intelletto]+7.311 Tempra\n[q2]+ 624 Critico\n[q2]+ 468 Maestria\nIntegrità 55 / 55\n[q2]Equipaggia: Gli incantesimi e le abilità hanno una probabilità di scatenare il potere della Luce contro i nemici. Una Scintilla di Beledar li giudica, infliggendo 86350 danni da radiosità e marchiandoli. La successiva Scintilla di Beledar consuma il marchio sul bersaglio per infliggere 74015 danni da radiosità aggiuntivi.\n80"}
MultiLanguageSpellData['it'][444074] = {name = "Aiuto dei Cavalieri", additional_info = "[q]Mentre ti stanno aiutando, i Cavalieri lanciano occasionalmente lo Scudo Antimagia su di te e su se stessi al 80% dell'efficacia.\n\n Si può beneficiare di questo effetto solo una volta ogni 45 s."}
MultiLanguageSpellData['it'][444081] = {name = "Rosso Fuoco", additional_info = "[q]Aumenta i danni inflitti e le cure fornite da Avvolgimento del 20% e le sue cariche di 1."}
MultiLanguageSpellData['it'][444082] = {name = "Libertà", additional_info = "[q0][Item Effect][q]Elusione aumentata del 20%.\n Gli alleati entro 40 m vengono immediatamente purificati dagli effetti di perdita di controllo del personaggio. L'effetto può verificarsi solo una volta ogni 45 s."}
MultiLanguageSpellData['it'][444083] = {name = "Patto dell'Apocalisse", additional_info = "[q]Quando si subiscono danni, il 5% dei danni subiti viene reindirizzato su ciascun Cavaliere attivo."}
MultiLanguageSpellData['it'][444088] = {name = "Consumo Fiamma", additional_info = "[q]Conservazione\n Avvolgimento consuma 2 s di Soffio del Sogno sul bersaglio, facendolo detonare e fornendo cure a tutti i bersagli vicini pari al 300% dell'ammontare consumato. Danni e cure ridotti oltre 5 bersagli.\n\nDevastazione\n Avvolgimento consuma 2 s di Soffio di Fuoco sul bersaglio, facendolo detonare e infliggendo danni a tutti i bersagli vicini pari al 900% dell'ammontare consumato. Danni e cure ridotti oltre 5 bersagli."}
MultiLanguageSpellData['it'][444089] = {name = "Consumo Fiamma", additional_info = "Portata di 100 m\nIstantaneo\n[q]Conservazione\nAvvolgimento consuma 2 s di Soffio del Sogno sul bersaglio, facendolo detonare e fornendo cure a tutti i bersagli vicini pari al 900% dell'ammontare consumato. Danni e cure ridotti oltre 5 bersagli.\n\nDevastazione\nAvvolgimento consuma 2 s di Soffio di Fuoco sul bersaglio, facendolo detonare e infliggendo danni a tutti i bersagli vicini pari al 900% dell'ammontare consumato. Danni e cure ridotti oltre 5 bersagli."}
