MultiLanguageSpellData['it'][444248] = {name = "Evocazione: Mograine", additional_info = "Istantaneo\n[q]Consumare rune ha una probabilità di richiamare in aiuto un Cavaliere per 10 s.\n\nMograine\n Lancia sulla propria posizione un effetto di Morte e Distruzione che lo segue.\n\nBiancachioma\n Lancia Non Morte sul bersaglio, infliggendo ([9.15376% of Attack Power]) danni da ombrogelo per accumulo ogni 3 s per 24 s. Ogni volta che Non Morte infligge danni, si accumula. L'effetto non può essere rinnovato.\n\nCacciatroll\n Lancia Catene di Ghiaccio sul bersaglio, riducendone la velocità di movimento del 40% e aumentando i danni da te inflitti a quel bersaglio del 5% per 8 s.\n\nNazgrim\n Finché Nazgrim è attivo, fornisce Conquista Apocalittica, che aumenta la Forza del 5%."}
MultiLanguageSpellData['it'][444249] = {name = "Soffio di Fuoco", additional_info = "Portata di 100 m\nIstantaneo\n[q]Inalare permette di alimentare il fuoco interiore. Espirare permette di bruciare i nemici in un cono frontale, infliggendo [(([163.409% of Spell Power])) + (([39.4834% of Spell Power]) * (10 + 0 ))] danni da fuoco. I danni inflitti si riducono oltre i 5 bersagli. [ Sabbie del Tempo : Aumenta la durata dei tuoi effetti di Vigore d'Ebano attivi di 2 s ]\n Potenziando l'abilità si aumentano i danni inflitti istantaneamente a discapito di quelli periodici.\n\nI: Infligge [([163.409% of Spell Power])] danni istantaneamente e [([39.4834% of Spell Power]) * (10 + 0 )] danni in (20 + 0 ) s.\n\nII: Infligge [([163.409% of Spell Power]) + (([39.4834% of Spell Power]) * 3)] danni istantaneamente e [([39.4834% of Spell Power]) * (7 + 0 )] danni in (14 + 0 ) s.\n\nIII: Infligge [([163.409% of Spell Power]) + (([39.4834% of Spell Power]) * 6)] danni istantaneamente e [([39.4834% of Spell Power]) * (4 + 0 )] danni in (8 + 0 ) s."}
MultiLanguageSpellData['it'][444250] = {name = "Torrente Fulminante", additional_info = "Portata illimitata\nIstantaneo\n[q]Quando raggiunge 100 energia, Kyrioss vola al centro della stanza e si sovraccarica di energia del fulmine, infliggendo 1212225 danni da natura e affliggendo i bersagli con Dardo Vincolante ogni 3 s per 15 s. Inoltre, scatena 4 torrenti di fulmini. Toccare questi torrenti infligge 19395595 danni da natura e stordisce il bersaglio per 6 s."}
MultiLanguageSpellData['it'][444251] = {name = "Evocazione: Biancachioma", additional_info = "Istantaneo\n[q]Consumare rune ha una probabilità di richiamare in aiuto un Cavaliere per 10 s.\n\nMograine\n Lancia sulla propria posizione un effetto di Morte e Distruzione che lo segue.\n\nBiancachioma\n Lancia Non Morte sul bersaglio, infliggendo ([9.15376% of Attack Power]) danni da ombrogelo per accumulo ogni 3 s per 24 s. Ogni volta che Non Morte infligge danni, si accumula. L'effetto non può essere rinnovato.\n\nCacciatroll\n Lancia Catene di Ghiaccio sul bersaglio, riducendone la velocità di movimento del 40% e aumentando i danni da te inflitti a quel bersaglio del 5% per 8 s.\n\nNazgrim\n Finché Nazgrim è attivo, fornisce Conquista Apocalittica, che aumenta la Forza del 5%."}
MultiLanguageSpellData['it'][444252] = {name = "Evocazione: Nazgrim", additional_info = "Istantaneo\n[q]Consumare rune ha una probabilità di richiamare in aiuto un Cavaliere per 10 s.\n\nMograine\n Lancia sulla propria posizione un effetto di Morte e Distruzione che lo segue.\n\nBiancachioma\n Lancia Non Morte sul bersaglio, infliggendo ([9.15376% of Attack Power]) danni da ombrogelo per accumulo ogni 3 s per 24 s. Ogni volta che Non Morte infligge danni, si accumula. L'effetto non può essere rinnovato.\n\nCacciatroll\n Lancia Catene di Ghiaccio sul bersaglio, riducendone la velocità di movimento del 40% e aumentando i danni da te inflitti a quel bersaglio del 5% per 8 s.\n\nNazgrim\n Finché Nazgrim è attivo, fornisce Conquista Apocalittica, che aumenta la Forza del 5%."}
MultiLanguageSpellData['it'][444254] = {name = "Evocazione: Cacciatroll", additional_info = "Istantaneo\n[q]Consumare rune ha una probabilità di richiamare in aiuto un Cavaliere per 10 s.\n\nMograine\n Lancia sulla propria posizione un effetto di Morte e Distruzione che lo segue.\n\nBiancachioma\n Lancia Non Morte sul bersaglio, infliggendo ([9.15376% of Attack Power]) danni da ombrogelo per accumulo ogni 3 s per 24 s. Ogni volta che Non Morte infligge danni, si accumula. L'effetto non può essere rinnovato.\n\nCacciatroll\n Lancia Catene di Ghiaccio sul bersaglio, riducendone la velocità di movimento del 40% e aumentando i danni da te inflitti a quel bersaglio del 5% per 8 s.\n\nNazgrim\n Finché Nazgrim è attivo, fornisce Conquista Apocalittica, che aumenta la Forza del 5%."}
MultiLanguageSpellData['it'][444256] = {name = "Globi Scheggiati", additional_info = "[q]Arcano\n I nemici danneggiati da Globo Arcano evocano 2 Scheggia Arcana, fino a un massimo di 4.\n\n Aumenta i danni inflitti da Globo Arcano del 25%.\n\nGelo\n I nemici danneggiati da Globo Congelato evocano 1 Scheggia di Gelo, fino a un massimo di 4.\n\n Aumenta i danni inflitti da Globo Congelato del 25%."}
