MultiLanguageSpellData['it'][444754] = {name = "Lancio Sfuggente", additional_info = "Istantaneo\n[q]Aumenta la velocità di movimento del 40% durante Riavvolgimento Temporale ."}
MultiLanguageSpellData['it'][444755] = {name = "Cera Ribollente", additional_info = "Cera Ribollente Livello 80\n[q0][Item Effect]3 s di lancio\nRichiede A distanza, A distanza, Due mani, Mano Secondaria, Mano primaria, Una mano\n[q]Ricopre le armi di Cera Ribollente per fino all'annullamento. Applicare effetti velenosi al bersaglio fornisce una probabilità di far gocciolare una pozza di cera bollente di 4 m sul bersaglio, infliggendo 297 danni da fuoco suddivisi tra i nemici.\n\n I danni aumentano per ogni nemico colpito, fino a un massimo di 5 nemici."}
MultiLanguageSpellData['it'][444756] = {name = "Illusionismo", additional_info = "[q]Aumenta la durata di Dislocazione del 50% e la sua portata del 25%."}
MultiLanguageSpellData['it'][444763] = {name = "Conquista Apocalittica", additional_info = "Portata illimitata\nIstantaneo\n[q]Quando Nazgrim è attivo, si ottiene Conquista Apocalittica, che aumenta la Forza del 5%."}
MultiLanguageSpellData['it'][444764] = {name = "Lame del Razziatore", additional_info = "Istantaneo\n[q]Consumare [ Rovina : 6 /\n\nVendetta\n20 ] Frammenti dell'Anima o lanciare A Caccia converte il successivo Lancio Lama in Lame del Razziatore.\n\n Lame del Razziatore :\nLancia una lama potenziata con l'essenza delle anime consumate contro il bersaglio, infliggendo ([345% of Attack Power]) danni fisici e saltando su 2 nemici aggiuntivi.\n\n Inizia a eseguire una sequenza magistrale con le lame, potenziando il successivo lancio di [ Rovina : Assalto del Caos / Frattura / Recisione ] e [ Rovina : Lame Danzanti /\n\nVendetta\nFendente d'Anima ]\n L'abilità potenziata lanciata per prima infligge il 10% di danni aggiuntivi e la seconda infligge il 20% di danni aggiuntivi."}
MultiLanguageSpellData['it'][444765] = {name = "Verifica", additional_info = nil}
MultiLanguageSpellData['it'][444766] = {name = "Verifica", additional_info = nil}
MultiLanguageSpellData['it'][444767] = {name = "Supremazia del Carnefice", additional_info = "Circa 7 apparenze ogni minuto\n[q]Gli attacchi contro il bersaglio primario hanno un'alta probabilità di travolgere le sue difese e scatenare un Assalto del Carnefice, infliggendo ([333.5% of Attack Power]) danni fisici e applicando Marchiato per l'Esecuzione, che ne aumenta i danni subiti dalla tua successiva Esecuzione del 15%. Si accumula fino a 3 volte."}
MultiLanguageSpellData['it'][444769] = {name = "Disfatta Imminente", additional_info = "[q]Ogni 3 Assalti del Carnefice si ottiene Morte Improvvisa.\n\n Usare Morte Improvvisa accelera la successiva Tempesta di Lame, che colpisce 1 volta aggiuntiva (fino a un massimo di 3). La durata totale di Tempesta di Lame resta invariata."}
MultiLanguageSpellData['it'][444770] = {name = "Pulsione Mortale", additional_info = "[q]Rigenera salute pari al 15% dei danni inflitti da Morte Improvvisa."}
MultiLanguageSpellData['it'][444771] = {name = "Senza Pietà", additional_info = "[q]Marchiato per l'Esecuzione aumenta la probabilità di critico e i danni critici inflitti dal successivo lancio di Esecuzione sul bersaglio del 15%."}
MultiLanguageSpellData['it'][444772] = {name = "Lame Travolgenti", additional_info = "[q]Ogni colpo di Tempesta di Lame applica l'effetto Sopraffatto a tutti i nemici colpiti, aumentando i danni che infliggi a quei bersagli del 1 % per 20 s. Si accumula fino a 10 volte."}
MultiLanguageSpellData['it'][444773] = {name = "Completamento Feroce", additional_info = "[q]Armi\n I colpi critici di Assalto Mortale aumentano i danni inflitti dal successivo lancio di Assalto Mortale del 20%.\n\nFuria\n I colpi critici di Sete di Sangue aumentano i danni inflitti dal successivo lancio di Sete di Sangue del 20%."}
MultiLanguageSpellData['it'][444774] = {name = "Opportunista", additional_info = "[q]Furia\n Quando Colpo Furente azzera il proprio tempo di recupero, il successivo Colpo Furente infligge il 20% di danni aggiuntivi e il 20% di danni critici aggiuntivi.\n\nArmi\n Quando Tatticismo azzera il tempo di recupero di Dominazione, la successiva Dominazione infligge il 25% di danni aggiuntivi e il 25% di danni critici aggiuntivi."}
MultiLanguageSpellData['it'][444775] = {name = "Mietitempesta", additional_info = "[q]Armi\n Quando Assalto Mortale e Fendente colpiscono 3 o più bersagli hanno una probabilità del 20% di scatenare una raffica d'acciaio, colpendo tutti i nemici vicini, infliggendo ([371.11% of Attack Power]) danni fisici e applicando l'effetto Sopraffatto. Danni ridotti oltre 8 bersagli.\n\nFuria\n Sete di Sangue ha una probabilità del 20% di scatenare una raffica d'acciaio, colpendo tutti i nemici vicini, infliggendo ([371.11% of Attack Power]) danni fisici e applicando l'effetto Sopraffatto. Danni ridotti oltre 8 bersagli.\n\n(Possibilità di Apparire:20%, 500ms di recupero)"}
MultiLanguageSpellData['it'][444776] = {name = "Inseguimento Implacabile", additional_info = "[q]Carica aumenta la velocità di movimento del 70% per 3 s.\n\n Carica dissolve tutti gli effetti di limitazione al movimento. Può verificarsi solo una volta ogni 30 s."}
MultiLanguageSpellData['it'][444777] = {name = "Agilità Brutale", additional_info = "[q]Balzo Eroico riduce il tempo di recupero di Carica di 5 s e Carica riduce il tempo di recupero di Balzo Eroico di 2 s."}
MultiLanguageSpellData['it'][444778] = {name = "Ciclone Epurante", additional_info = "[q]Ogni colpo di Tempesta di Lame infligge il 10% di danni aggiuntivi suddivisi equamente tra tutti i bersagli."}
MultiLanguageSpellData['it'][444779] = {name = "Malizia del Carnefice", additional_info = "[q]Furia\n Aumenta i danni inflitti da Colpo Furente del 30%.\n\nArmi\n Aumenta i danni inflitti da Dominazione del 30%."}
MultiLanguageSpellData['it'][444780] = {name = "Massacro Inarrestabile", additional_info = "[q]Quando si colpisce con Esecuzione un bersaglio Marchiato per l'Esecuzione, si riduce il tempo di recupero di Tempesta di Lame di 5 s e si applicano 2 accumuli di Sopraffatto sul bersaglio per ogni accumulo di Marchiato per l'Esecuzione consumato.\n\n Durante Tempesta di Lame è possibile lanciare Pugno Diversivo e Dardo della Tempesta."}
MultiLanguageSpellData['it'][444784] = {name = "Immagine Fantasma", additional_info = "[q]Immagine Speculare evoca un clone aggiuntivo.\n Immagine Speculare riduce tutti i danni subiti del 5% aggiuntivo."}
MultiLanguageSpellData['it'][444785] = {name = "Persico Cruento", additional_info = "Istantaneo\n[q]Un piccolo pesce dalle squame rosse che nuota a Khaz Algar. Se minacciato, le sue branchie emettono un inchiostro viscoso che sembra sangue.\n\nSpeciale:\n\n Esca di Sangue\n\n Rilanciare questo pesce nelle acque di Khaz Algar può attivare questo meccanismo, ricoprendoti di feromoni che attirano l'elusivo Pescecane Sanguinario.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Isola delle Sirene\n - Oasi di K'aresh\n\nPozze di Pesca:\n\n - Banco di Squali dei Bassifondi\n - Sangue in Acqua\n - Pozzamarcia Putrescente\n - Banco di Persici Cruenti\n - Increspatura sulla Superficie Calma\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444786] = {name = "Storione Cristallino", additional_info = "Portata di 5 m\nIstantaneo\n[q]Un pesce elegante e allungato che si muove agevolmente nelle acque di Khaz Algar. Di dimensioni molto più grandi rispetto al cugino, il Rodeo di Bismuto, questo pesce antico tende a spostarsi in banchi per assorbire i nutrienti rimossi dagli altri pesci.\n\nSpeciale:\n\n Percezione\n\n Rilancia questo pesce in acqua per aumentare la Percezione a Khaz Algar.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Isola delle Sirene\n\nPozze di Pesca:\n\n - Stagnolustro\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444787] = {name = "Rodeo di Bismuto", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Piccolo, con un'espressione che sembra faccia una smorfia, le sue scaglie dure ricordano da vicino il bismuto, anche perché intrappolano minerali e altri detriti che vengono poi trasportati per le acque di Khaz Algar. Un pesce molto comune ma fondamentale per la prosperità della flora locale.\n\nSpeciale:\n\n Esca\n\n Rilancia questo pesce in acqua per aumentare la Competenza in Pesca.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Isola delle Sirene\n\nPozze di Pesca:\n\n - Stagnolustro\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444788] = {name = "Sanguinerola Sgranocchiatrice", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Un pesciolino comune, che potrebbe indurre un pescatore inesperto a credere che il suo valore sia marginale. Invece, questi pesci sono famosi perché tendono a radunarsi attorno a oggetti particolarmente lucenti e a sgranocchiare via la sporcizia che raccolgono.\n\nSpeciale:\n\n Percezione\n\n Rilancia questo pesce in acqua per aumentare la Percezione a Khaz Algar.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Azj-Kahet\n - Isola delle Sirene\n - Cavafonda\n - Oasi di K'aresh\n\nPozze di Pesca:\n\n - Increspatura sulla Superficie Calma\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444789] = {name = "Lucerna Sussurrante", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Abituato a formare banchi compatti, questo pesce prende il nome dall'attrito che le sue scaglie nere come l'inchiostro producono oscillando l'una contro l'altra. Queste vibrazioni agiscono come deterrente per i predatori e creano un suono ben udibile anche in superficie.\n\nSpeciale:\n\n Sussurri delle Profondità\n\n Usa la Lucerna Sussurrante per tirar fuori dei Celacanti Dormienti dalle profondità di Azj-Kahet.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Isola delle Sirene\n - Oasi di K'aresh\n\nPozze di Pesca:\n\n - Banco di Lucerne\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444790] = {name = "Trota Branchiadoro", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]L'interno delle branchie brilla di un colore dorato cangiante. I pescatori credono che porti fortuna e calmi le acque.\n\nSpeciale:\n\n Percezione\n\n Pescare questo pesce aumenta la Percezione a Khaz Algar.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Azj-Kahet\n - Isola delle Sirene\n - Cavafonda\n - Oasi di K'aresh\n\nPozze di Pesca:\n\n - Stagnolustro\n - Pozzamarcia Putrescente\n - Sversamento di Icore Infuso\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444791] = {name = "Pesce Arcobaleno Speculare", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]È il sangue variopinto che scorre sotto le scaglie traslucide a conferire a questo pesce il suo aspetto arcobaleno. A parte la carne che si può usare in Cucina, il sangue del Pesce Arcobaleno è quasi identico al Pigmento di Madreperla usato dai runografi.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre del Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Isola delle Sirene\n - Oasi di K'aresh\n\nPozze di Pesca:\n\n - Stagnolustro\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444792] = {name = "Leucisco Procrastinatore", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Un pesce dispettoso che sfreccia a Khaz Algar. Spesso confuso per una Sanguinerola Sgranocchiatrice o uno Pseudocromide Regale, la sua velocità e le sue dimensioni gli permettono di trovarsi dove non dovrebbe.\n\nSpeciale:\n\n Esca\n\n Rilancia questo pesce in acqua per aumentare la Competenza in Pesca.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Isola delle Sirene\n - Oasi di K'aresh\n\nPozze di Pesca:\n\n - Increspatura sulla Superficie Calma\n - Sangue in Acqua\n - Pozzamarcia Putrescente\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444793] = {name = "Luccio di Dorn", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Una creatura senza pretese il cui aspetto esterno la mimetizza dagli attacchi dall'alto permettendole di catturare i pesci più piccoli sottostanti. È grande e carnoso all'esterno, quasi come lo Storione Cristallino, ed è un'eccellente fonte di filetto fresco.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre del Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Isola delle Sirene\n\nPozze di Pesca:\n\n - Increspatura sulla Superficie Calma\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444794] = {name = "Grandocchio Ruggente", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Un pesce aggressivo che tende a radunarsi dove si ritrovano i pescatori. La potente pinna caudale e il corpo muscoloso squarciano le onde creando un sonoro ruggito.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre del Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Azj-Kahet\n - Isola delle Sirene\n\nPozze di Pesca:\n\n - Torrente di Grandocchio\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444795] = {name = "Pesce Martello di Arathor", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]La corona che questo pesce ha sulla testa è un'arma formidabile, quando viene spinta dalle enormi pinne. Con le scaglie che brillano di una tonalità simile a quella degli Arathi, non c'è da meravigliarsi del nome di questo muscoloso pesce.\n\nSpeciale:\n\n Caduta del Martello\n\nColpisce il nemico con un Pesce Martello di Arathor e lo stordisce per 1 s. Utilizzabile solo all'esterno a Khaz Algar.\n\nAree in cui si può trovare questo pesce:\n\n - Precipizi Sacri\n\nPozze di Pesca:\n\n - Sangue in Acqua\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444796] = {name = "Pseudocromide Regale", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Strisce cremisi e magenta sfumate attraversano il piccolo ma potente torso di questo pesce, particolarmente raro e aggressivo. Ottimo per proteggere le acque intorno al Pesce Lanterna della Regina dai Pesci Ghoul corrotti.\n\nSpeciale:\n\n Esca Reale\n\n Allontana i Pesci Ghoul corrotti per creare acque sicure per il Pesce Lanterna della Regina.\n\nAree in cui si può trovare questo pesce:\n\n - Precipizi Sacri\n - Azj-Kahet\n\nPozze di Pesca:\n\n - Increspatura Regale\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444797] = {name = "Squalo dei Bassifondi Kaheti", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Questa creatura scivola sui fondali delle acque nelle profondità di Azj-Kahet, una sagoma appena distinguibile dall'oscurità. È un predatore calcolatore che fa confidare nella fortuna anche i pescatori più esperti.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre una grande quantità di Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Precipizi Sacri\n - Azj-Kahet\n\nPozze di Pesca:\n\n - Sangue in Acqua\n - Sciame di Squali dei Bassifondi\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444798] = {name = "Ombropesce Pallido", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Spesso scambiato per un Pesce Ghoul corrotto, questo grosso pesce è in realtà il migliore amico dei pescatori. Attratto dai minerali sui fondali, l'Ombropesce Pallido ha la tendenza a ingoiare tesori nascosti.\n\nSpeciale:\n\n Stomaco d'Ombropesce\n\n Apri lo stomaco del pesce sperando di trovare qualche tesoro.\n\nAree in cui si può trovare questo pesce:\n\n - Azj-Kahet\n - Cavafonda\n\nPozze di Pesca:\n\n - Sversamento di Icore Infuso\n - Pozzamarcia Putrescente\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444799] = {name = "Pescecane Sanguinario", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Maestro delle imboscate, il Pescecane Sanguinario nuota pazientemente sulla scia dei pesci più piccoli prima di usare le sue pinne cremisi per scattare. Questo pesce grande e sfuggente è attratto principalmente dai banchi di pesce di Persico Cruento.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre una grande quantità di Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Precipizi Sacri\n - Azj-Kahet\n - Isola delle Sirene\n - Oasi di K'aresh\n\nPozze di Pesca:\n\n - Banco di Persici Cruenti\n - Sangue in Acqua\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444800] = {name = "Corvo di Mare Spinoso", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Il suo corpo è adornato da spine aguzze che sporgono da varie angolazioni, come una temibile armatura. Queste spine servono sia da protezione che da mimetizzazione per i fondali rocciosi dove spesso dimora. Nonostante l'aspetto fuori dal comune, si muove con grazia sorprendente, scivolando senza fatica tra anfratti e grotte sottomarine.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre una grande quantità di Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Precipizi Sacri\n - Isola delle Sirene\n\nPozze di Pesca:\n\n - Increspatura sulla Superficie Calma\n - Stagnolustro\n - Banco di Lucerne\n - Torrente di Grandocchio\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444801] = {name = "Pesce Lanterna della Regina", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Il suo corpo allungato è ornato da scaglie iridescenti che brillano di una moltitudine di colori. Un'esca bioluminescente pende davanti alla fronte, simile a un gioiello luminoso. Con grazia, questo pesce scivola attraverso le profondità oscure di Khaz Algar, a proprio agio negli abissi grazie ai sensi estremamente acuti.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre una grande quantità di Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Precipizi Sacri\n - Azj-Kahet\n\nPozze di Pesca:\n\n - Increspatura Regale\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444802] = {name = "Pesce Ghoul Maledetto", additional_info = "Portata di 5 m\nIstantaneo\n[q]Distorto dal sangue degli Dei Antichi, la sua pelle pallida e malaticcia ricopre un corpo scheletrico. I pescatori di Khaz Algar parlano di questo pesce come di un messaggero di sventura, maledicendo i pescatori abbastanza sfortunati da pescarlo. Guardare negli occhi questa creatura ne alimenta la malvagità, poiché ogni riflesso viene consumato dall'abisso.\n\nPescare questo pesce lancia:\n\n Maledizione del Pesce Ghoul\n\n Comunque, non ogni speranza è perduta. Laddove i pescatori evitano i Pesci Ghoul Maledetti, i cuochi vedono un'opportunità. Recuperare questo pesce può fornire benefici allo stomaco e migliorare la Competenza in Pesca.\n\nAree in cui si può trovare questo pesce:\n\n - Ovunque un pescatore Algari voglia gettare l'amo.\n\nPozze di Pesca:\n\n - Tutte le pozze\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444803] = {name = "Celacanto Risvegliato", additional_info = "Portata di 5 m\nIstantaneo\n[q]Una creatura umile e dormiente. Quando è sveglio, le sue scaglie brillano anche se è presente poca luce. Una maestosità silenziosa, un obiettivo adatto a ogni aspirante pescatore.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre una grande quantità di Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Azj-Kahet\n - Oasi di K'aresh\nProfessione:\nPesca"}
MultiLanguageSpellData['it'][444806] = {name = "Furia degli Aldrachi", additional_info = "Istantaneo\n[q]Consumare [ Rovina : 6 /\n\nVendetta\n20 ] Frammenti dell'Anima o lanciare A Caccia converte il successivo Lancio Lama in Lame del Razziatore.\n\n Lame del Razziatore :\nLancia una lama potenziata con l'essenza delle anime consumate contro il bersaglio, infliggendo ([345% of Attack Power]) danni fisici e saltando su 2 nemici aggiuntivi.\n\n Inizia a eseguire una sequenza magistrale con le lame, potenziando il successivo lancio di [ Rovina : Assalto del Caos / Frattura / Recisione ] e [ Rovina : Lame Danzanti /\n\nVendetta\nFendente d'Anima ]\n L'abilità potenziata lanciata per prima infligge il 10% di danni aggiuntivi e la seconda infligge il 20% di danni aggiuntivi."}
MultiLanguageSpellData['it'][444808] = {name = "Richiesta d'Aiuto", additional_info = nil}
MultiLanguageSpellData['it'][444810] = {name = "Arte delle Lame", additional_info = "Portata di 8 m\nIstantaneo\n[q]Vendetta\nConsumare un Frammento dell'Anima fa sì che il successivo lancio di infligga ([40% of Attack Power]) danni fisici aggiuntivi.\n\nRovina\nConsumare un Frammento dell'Anima fa sì che il successivo lancio di Assalto del Caos infligga ([40% of Attack Power]) danni fisici aggiuntivi.\n\n Vilspada consuma fino a 5 Frammenti dell'Anima vicini."}
MultiLanguageSpellData['it'][444811] = {name = "Evocazione: Globo dei Titani", additional_info = nil}
