MultiLanguageSpellData['it'][445024] = {name = "Elementi Turbinanti", additional_info = "[q]Rigenerazione\n Granuli elementali orbitano attorno al Totem Crescente. Le tue abilità consumano i granuli per ottenerne effetti potenziati.\n\nAcqua: La successiva Ondata di Cura o Eruzione Benefica cura anche un alleato all'interno dell'area d'effetto di Pioggia Curativa al 100% dell'efficacia.\n\nAria: [ Potenziamento : Il successivo lancio di Dardo Fulminante, Catena di Fulmini o Detonazione Elementale scatena 3 Dardi Crescenti sul Totem Crescente /\n\nElementale, Rigenerazione\nRiduce il tempo di lancio del successivo incantesimo di cura del 40% ]\nTerra: [ Potenziamento : Aumenta i danni diretti del successivo lancio di Folgore del Fuoco del 300% e ne applica l'effetto a 5 nemici vicini /\n\nElementale, Rigenerazione\nIl successivo lancio di Catena di Guarigione fornisce Terra Benefica a tutti i bersagli colpiti al 150% dell'efficacia ]\nPotenziamento\n Granuli elementali orbitano attorno al Totem Crescente. Le tue abilità consumano i granuli per ottenerne effetti potenziati.\n\nAria: [ Potenziamento : Il successivo lancio di Dardo Fulminante, Catena di Fulmini o Detonazione Elementale scatena 3 Dardi Crescenti sul Totem Crescente /\n\nElementale, Rigenerazione\nRiduce il tempo di lancio del successivo incantesimo di cura del 40% ]\nTerra: [ Potenziamento : Aumenta i danni diretti del successivo lancio di Folgore del Fuoco del 300% e ne applica l'effetto a 5 nemici vicini /\n\nElementale, Rigenerazione\nIl successivo lancio di Catena di Guarigione fornisce Terra Benefica a tutti i bersagli colpiti al 150% dell'efficacia ]\nFuoco: Il successivo lancio di Sferzata Lavica o Esplosione di Fuoco fornisce Mano Ardente per 6 s."}
MultiLanguageSpellData['it'][445025] = {name = "Rimbalzo Totemico", additional_info = "Circa 10 apparenze ogni minuto\n[q]Potenziamento\n Dardo Fulminante, Catena di Fulmini e Detonazione Elementale hanno una probabilità di scatenare un Dardo Crescente su un Totem Crescente, aumentandone i danni inflitti del 10%, reindirizzando poi il dardo sul bersaglio e infliggendo ([92% of Attack Power]) danni da natura. L'effetto di bonus ai danni si accumula.\n\nRigenerazione\n Quando raggiunge l'ultimo dei bersagli, Catena di Guarigione salta su un totem entro 20 m, facendogli lanciare Catena di Guarigione su un alleato ferito entro 30 m e curandolo di ([150% of Spell Power]). Questa catena salta su 2 bersagli entro 20 m."}
MultiLanguageSpellData['it'][445026] = {name = "Totem Giganti", additional_info = "[q]Aumenta le dimensioni e il raggio dei tuoi totem del 15%, e la loro salute del 30%."}
MultiLanguageSpellData['it'][445027] = {name = "Richiamo Lesto", additional_info = "[q]Dissolvere un effetto dannoso con il Totem del Tremore o il Totem della Purificazione del Veleno, oppure controllare un nemico con il Totem della Condensazione Elettrica o il Totem della Presa della Terra, riduce il tempo di recupero del totem usato di 5 s.\n\n Non può attivarsi più di una volta ogni 20 s per totem."}
MultiLanguageSpellData['it'][445028] = {name = "Maestria nelle Infusioni", additional_info = "[q]Rigenerazione\n Aumenta la durata dell'effetto Terra Benefica di 3 s.\n\nPotenziamento\n Aumenta la probabilità che Arma della Furia del Vento si attivi del 5% e ne aumenta i danni inflitti del 8%.\n\n Quando Arma della Lingua di Fuoco si attiva con gli attacchi di Arma della Furia del Vento, ha una probabilità di scatenare un turbine di fiamme attorno al bersaglio, infliggendo il 300% dei danni a tutti i nemici vicini."}
MultiLanguageSpellData['it'][445029] = {name = "Nucleo d'Amplificazione", additional_info = "[q]Quando il Totem Crescente è attivo, i danni inflitti e le cure fornite aumentano del 3%."}
MultiLanguageSpellData['it'][445030] = {name = "Superimpeto", additional_info = "[q]Rigenerazione\n Aumenta i danni inflitti dal Totem Crescente del 50% durante Ascesa.\n\nPotenziamento\n Aumenta i danni inflitti dal Totem Crescente del 50% durante Ascesa."}
MultiLanguageSpellData['it'][445031] = {name = "Barriera di Vento", additional_info = "[q]Se c'è un totem attivo, i totem forniscono uno scudo che assorbe ([Total Health] * 6 / 100) danni subiti ogni 30 s per 30 s."}
MultiLanguageSpellData['it'][445032] = {name = "Condensatore d'Impulsi", additional_info = "[q]Potenziamento\n Aumenta i danni inflitti dal Totem Crescente del 18%.\n\nRigenerazione\n Aumenta le cure fornite dal Totem Crescente del 25%."}
MultiLanguageSpellData['it'][445033] = {name = "Infusioni di Supporto", additional_info = "[q]Rigenerazione\n Apprendi una nuova Infusione dell'Arma: Guardia dell'Invocatore delle Maree.\n\n Guardia dell'Invocatore delle Maree\nInfonde lo scudo con l'elemento dell'acqua per 1 ora. Aumenta le cure fornite del 2.0% e la durata del Totem del Flusso Vitale e del Totem del Nubifragio di 3.0 s. \n\nPotenziamento\n Aumenta la probabilità di critico di Arma della Lingua di Fuoco del 25% e i danni critici che infligge del 100%."}
MultiLanguageSpellData['it'][445034] = {name = "Totem Vivaci", additional_info = "[q]Rigenerazione\n Quando viene evocato un Totem della Marea Curativa, un Totem del Flusso Vitale, un Totem del Nubifragio o un Totem del Collegamento Spirituale, si lancia una Catena di Guarigione istantanea e priva di costo al 100% dell'efficacia.\n\nPotenziamento\n Sferzata Lavica ha una probabilità di evocare un Totem delle Fiamme che lancia Dardi Roventi, infliggendo ([48.3% of Spell Power]) danni da fuoco a un nemico vicino. Dura 8 s.\n\n I lanci di Folgore del Gelo potenziati da Tempesta di Grandine, Sferzata Lavica ed Esplosione di Fuoco fanno sì che i Totem delle Fiamme scaglino una Raffica Rovente su massimo 5 nemici vicini, infliggendo ([92.736% of Spell Power]) danni da fuoco."}
MultiLanguageSpellData['it'][445035] = {name = "Reattività", additional_info = "[q]Rigenerazione\n I Totem del Flusso Vitale ora curano un secondo alleato al 100% dell'efficacia.\n\n Il Totem del Nubifragio accumula il 25% di cure aggiuntive.\n\nPotenziamento\n Mentre l'effetto di Mano Ardente è attivo, Sferzata Lavica frantuma la terra, lanciando una Scissione al 50% dell'efficacia.\n\n Le Scissioni lanciate da questo effetto non inabilitano."}
MultiLanguageSpellData['it'][445036] = {name = "Coordinazione Totemica", additional_info = "[q]Rigenerazione\n Aumenta l'efficacia delle Catene di Guarigione lanciate da Totem Vivaci e Rimbalzo Totemico del 25%.\n\nPotenziamento\n Aumenta la probabilità di critico degli attacchi del Totem delle Fiamme del 15% e i danni critici che infligge del 30%."}
