MultiLanguageSpellData['it'][445323] = {name = "[q4]Verga Runica di Pietra del Nulla", additional_info = "3.5 s di lancio 2\nStrumenti:\nVerga Runica d'Incantamento\nReagenti:\nIntuito dell'Artigiano (400), Lingotto delle Profondità Risonanti (2), Pietra del Nulla , Polvere di Tempesta (100), Scheggia Luccicante (10)\nReagenti Facoltativi:\nPersonalizza statistiche di creazione (#345) , Incantamenti ed equipaggiamento (#378) , Autenticità dell'Artigiano (#354)\nMercante:\nLyrendal\nZona:\nDornogal\nCosto:\n150\n\n[q4]Verga Runica di Pietra del Nulla\nSi vincola alla raccolta\nAttrezzo di Incantamento\n[q2]+ 125 Attributo casuale 1\n[q2]Equipaggia: Aumenta la Competenza in Incantamento di Khaz Algar di 18.\n[q2]Equipaggia: Riduce la Concentrazione consumata del 1% quando ci si concentra sulle ricette d'Incantamento di Khaz Algar.\n68\n[q]\"Può essere usata come una Verga Runica.\""}
MultiLanguageSpellData['it'][445324] = {name = "[q3]Bacchetta di Legno Incantata", additional_info = "3.5 s di lancio 3\nStrumenti:\nVerga Runica d'Incantamento\nReagenti:\nPolvere di Tempesta (5), Legnoverde Codificato\nReagenti Facoltativi:\nPotenzia (#342) , Aggiungi abbellimento (#341) , Personalizza statistiche secondarie (#365) , Incantamenti ed equipaggiamento (#378) , Autenticità dell'Artigiano (#354)\nIstruttore delle Professioni:\nIncantamento di Khaz Algar (40)\nCosto:\n150\n\n[q3]Bacchetta di Legno Incantata\nSi vincola all'equipaggiamento\nA distanza Bacchetta\n270 - 451 Danni da Ombra Velocità 2.00\n(180.3 danni per secondo)\n+1.847 Intelletto\n+1.162 Tempra\n[q2]+ 222 Attributo casuale 1\n[q2]+ 222 Attributo casuale 2\nIntegrità 90 / 90\n72"}
MultiLanguageSpellData['it'][445347] = {name = "[q4]Emblema dell'Aralda Runico Incantato", additional_info = "3.5 s di lancio 2\nStrumenti:\nVerga Runica d'Incantamento\nReagenti:\nEmblema dell'Aralda Runico Nascente , Polvere di Tempesta (60), Scheggia Luccicante (10), Cristallo Rifulgente\nBottino:\nAll'avventura a Khaz Algar\n\n[q4]Emblema dell'Aralda Runico Incantato\nSi vincola alla raccolta\nReagente d'Artigianato Facoltativo\n[q2]+10 Difficoltà ricetta\n[q2]Fornisce la seguente proprietà: Imposta il livello oggetto in base alla Qualità Artigianato (606-619).\n[q]Utilizzabile con: Ricette di Khaz Algar per equipaggiamento epico creato con una Scintilla dei Presagi.\n[q]\"Un potente reagente creato dagli incantatori.\""}
MultiLanguageSpellData['it'][445354] = {name = "[q4]Emblema dell'Aralda Dorato Incantato", additional_info = "3.5 s di lancio 3\nStrumenti:\nVerga Runica d'Incantamento\nReagenti:\nEmblema dell'Aralda Dorato Nascente , Polvere di Tempesta (100), Scheggia Luccicante (15), Cristallo Rifulgente (2)\nBottino:\nAll'avventura a Khaz Algar\n\n[q4]Emblema dell'Aralda Dorato Incantato\nSi vincola alla raccolta\nReagente d'Artigianato Facoltativo\n[q2]+20 Difficoltà ricetta\n[q2]Fornisce la seguente proprietà: Imposta il livello oggetto in base alla Qualità Artigianato (623-636).\n[q]Utilizzabile con: Ricette di Khaz Algar per equipaggiamento epico creato con una Scintilla dei Presagi.\n[q]\"Un potente reagente creato dagli incantatori.\""}
MultiLanguageSpellData['it'][445355] = {name = "[q4]Scettro delle Magie Radiose", additional_info = "3.5 s di lancio 3\nStrumenti:\nVerga Runica d'Incantamento\nReagenti:\nAccendifiamma Profanato (2), Scheggia Luccicante (6), Cristallo Rifulgente (2), Legnoverde Codificato , Scintilla (#256)\nReagenti Facoltativi:\nInfondi di potere (#366) , Aggiungi abbellimento (#341) , Personalizza statistiche secondarie (#365) , Incantamenti ed equipaggiamento (#378) , Autenticità dell'Artigiano (#354) , Oltre l'Immaginabile (#384)\nSpecializzazione:\nEffimeri, Arricchimenti ed Equipaggiamento - Creazioni da Combattimento\n\n[q4]Scettro delle Magie Radiose\nSi vincola alla raccolta\nA distanza Bacchetta\n907 - 1,513 Danni da Fuoco Velocità 2.00\n(605.0 danni per secondo)\n+6.201 Intelletto\n+4.874 Tempra\n[q2]+ 364 Attributo casuale 1\n[q2]+ 364 Attributo casuale 2\nIntegrità 110 / 110\n70"}
