MultiLanguageSpellData['it'][445475] = {name = "Raffica dei Sureki", additional_info = "Raffica dei Sureki Livello 80\nIstantaneo\n[q]Estrae un arco dall'arsenale per scatenare una raffica di frecce frontali, infliggendo ( 1 * 1478 ) danni da ombra a tutti i nemici entro 20 m.\n\n Finché non viene estratta l'arma successiva, restare fermi aumenta la velocità di movimento quando ci si muove del 6% per 6 s, aumentata del 6% aggiuntivo ogni 2 s, fino a un massimo di 5 volte."}
MultiLanguageSpellData['it'][445479] = {name = "[q2]Nettare Cinereo", additional_info = "2 s di lancio\nReagenti:\nBorraccia da Scorribanda (3), Frammento di Favo Caldo\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 10 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nCendvin\nZona:\nIsola di Dorn\nCosto:\n120\n\n[q2]Nettare Cinereo\n[q2]Usa: Rigenera ( 937500 / 5 * 20) mana in 20 s. Devi sederti per bere.\n68"}
MultiLanguageSpellData['it'][445480] = {name = "[q2]Sprintapasso", additional_info = "2 s di lancio\nReagenti:\nBorraccia da Scorribanda (5)\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 1 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nCapitana Giuramyt\nZona:\nPrecipizi Sacri\nCosto:\n10\n\n[q2]Sprintapasso\n[q2]Usa: Rigenera ( 937500 / 5 * 20) mana in 20 s. Devi sederti per bere.\n\n Sprintapasso\n Se bevi per almeno 10 s guadagni 167 velocità di movimento e l'abilità di camminare sull'acqua per 10 min.\n68"}
MultiLanguageSpellData['it'][445482] = {name = "[q2]Frappé di Frana", additional_info = "2 s di lancio\nReagenti:\nBorraccia da Scorribanda (5), Uova Strapazzate Spugnose (3), Frammento di Favo Caldo , Bismuto (10)\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 10 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nCapitana Giuramyt\nZona:\nPrecipizi Sacri\nCosto:\n10\n\n[q2]Frappé di Frana\n[q2]Usa: Non è stato frullato bene... (5 Min Recupero)\n68\n[q]\"Il dolcetto perfetto per i Terrigeni nelle giornate più calde a Khaz Algar.\""}
MultiLanguageSpellData['it'][445483] = {name = "[q2]Dolcetto Appiccicaticcio", additional_info = "2 s di lancio\nReagenti:\nUova Strapazzate Spugnose (3), Frammento di Favo Caldo , Farina Raggrumata (5), Polvere dell'Arteria del Nucleo (5)\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 10 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nBottino:\nMutastirpe Ovi'nax\nZona:\nPalazzo dei Nerub'ar\nRicetta:\nAcquistabile alla Casa d'Aste\n\n[q2]Dolcetto Appiccicaticcio\n[q2]Usa: Permette di tornare bambini! (5 Min Recupero)\n68\n[q]\"Il miele delle Api di Cenere proveniente dalla rete di caverne superiori è una prelibatezza per i giovani Nerubiani.\""}
MultiLanguageSpellData['it'][445484] = {name = "[q2]Barretta di Candela Sciolta", additional_info = "2 s di lancio\nReagenti:\nUova Strapazzate Spugnose (3), Frammento di Favo Caldo , Farina Raggrumata (5)\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 10 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nCapitana Giuramyt\nZona:\nPrecipizi Sacri\nCosto:\n10\n\n[q2]Barretta di Candela Sciolta\n[q2]Usa: Che male fa provare? (5 Min Recupero)\n68\n[q]\"Un equilibrio perfetto tra gommoso e croccante. Impossibile immaginare di condividerla con qualcun altro.\""}
