MultiLanguageSpellData['it'][447867] = {name = "Kah, Re degli Abissi", additional_info = "3.2 s di lancio\n[q]Distorto dal sangue degli Dei Antichi, la sua pelle pallida e malaticcia ricopre un corpo scheletrico. I pescatori di Khaz Algar parlano di questo pesce come di un messaggero di sventura, maledicendo i pescatori abbastanza sfortunati da pescarlo. Guardare negli occhi questa creatura ne alimenta la malvagità, poiché ogni riflesso viene consumato dall'abisso."}
MultiLanguageSpellData['it'][447868] = {name = "[q3]Trattato Algari sulla Runografia", additional_info = "3.5 s di lancio\nReagenti:\nResiduo di Linea di Faglia (2), Cifrario Sterminato , Inchiostro Assolato (2)\nSpecializzazione:\nRicerca della Conoscenza\n\n[q3]Trattato Algari sulla Runografia\n[q7]Si vincola alla Brigata\n[q2]Usa: Da studiare per aumentare la Conoscenza della Runografia di Khaz Algar di 1. (5 S Recupero)\nRichiedeRunografia di Khaz Algar\n(25)"}
