MultiLanguageSpellData['it'][447872] = {name = "[q2]Uova Strapazzate Spugnose", additional_info = "2 s di lancio\nReagenti:\nBorraccia da Scorribanda , Polvere d'Uovo Fine (10)\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 1 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nPolo\nZona:\nCittà dei Fili\nCosto:\n1.500\n\n[q2]Uova Strapazzate Spugnose\n[q2]Usa: Rigenera ( 375000 / 5 * 20) salute in 20 s. Devi sederti per mangiare.\n\n Ben Nutrito\n Se mangi per almeno 10 s diventi Ben Nutrito e guadagni [ 470 * (0.7)] della tua statistica secondaria più bassa per 15 min.\n68"}
MultiLanguageSpellData['it'][447873] = {name = "[q3]Salsa Segreta", additional_info = "2 s di lancio\nReagenti:\nPolvere d'Uovo Fine (5), Tuorlo Coagulato , Borraccia da Scorribanda\n[q]Una ricetta per 1 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nScoperta:\nIngredienti Preparati - Polvere d'Uovo Fine\n\n\n[q3]Salsa Segreta\n68"}
MultiLanguageSpellData['it'][447874] = {name = "[q2]Biscotti Piccoli Amici", additional_info = "2 s di lancio\nReagenti:\nTuorlo Coagulato , Uova Strapazzate Spugnose (4), Farina Raggrumata (5)\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 3 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nTyro Whalekk\nZona:\nCittà dei Fili\nCosto:\n1.500\n\n[q2]Biscotti dei Piccoli Amici\n[q2]Usa: Rigenera il 100% della salute di tutte le tue mascotte e resuscita quelle morte.\n68\n[q]\"Creati davvero per i piccoli amici!\""}
MultiLanguageSpellData['it'][447875] = {name = "[q2]Speciale di Azj-Kahet", additional_info = "2 s di lancio\nReagenti:\nBorraccia da Scorribanda , Tuorlo Coagulato\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 1 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nAx'ill\nZona:\nCittà dei Fili\nCosto:\n1.500\n\nMercante:\nTej l'Imperitura\nZona:\nCittà dei Fili\nCosto:\n1.500\n\n[q2]Specialità di Azj-Kahet\n[q2]Usa: Aumenta la velocità di movimento del 20% nella Città dei Fili. Non utilizzabile all'esterno.\n68\n[q]\"Che città affascinante!\""}
MultiLanguageSpellData['it'][447876] = {name = "[q3]Delizia di Pesce Ghoul", additional_info = "2 s di lancio\nReagenti:\nPesce Ghoul Preparato , Stufato Semplice\nReagenti Facoltativi:\nIngrediente Segreto (#318)\n[q]Una ricetta per 5 porzione. Il numero di porzioni può variare in base alla competenza in Cucina.\nMercante:\nCapitana Giuramyt\nZona:\nPrecipizi Sacri\nCosto:\n10\n\n[q3]Delizia di Pesce Ghoul\nSi vincola alla raccolta\n[q2]Usa: Rigenera ( 375000 / 5 * 20) salute in 20 s. Devi sederti per mangiare.\n\n Ben Nutrito\n Se mangi per almeno 10 s diventi Ben Nutrito e guadagni 30 in Competenza in Pesca di Khaz Algar e 150 Percezione per 1 ora.\n75\n[q]\"Il peggior incubo di un pescatore è una prelibatezza per un cuoco.\""}
