MultiLanguageSpellData['it'][449629] = {name = "Fervore Demoniaco", additional_info = "[q]Afflizione\n La tua anima demoniaca infligge il 100% di danni aggiuntivi ai bersagli affetti da una tua Afflizione Instabile.\n\nDemonologia\n La tua anima demoniaca infligge il 100% di danni aggiuntivi al bersaglio primario di Mano di Gul'dan."}
MultiLanguageSpellData['it'][449631] = {name = "Mietitura Malvagia", additional_info = "[q]Afflizione\n Aumenta i danni inflitti dalla tua anima demoniaca del 10%.\n\n Consumare Notte Fonda nutre e fa apparire la tua entità demoniaca, che infligge ([240.402% of Spell Power]) danni da ombra al bersaglio.\n\nDemonologia\n Aumenta i danni inflitti dalla tua anima demoniaca del 10%.\n\n Consumare Nucleo Demoniaco nutre e fa apparire la tua entità demoniaca, che infligge [([240.402% of Spell Power]) * 0.4] danni da ombra al bersaglio."}
