MultiLanguageSpellData['it'][449634] = {name = "Quietus", additional_info = "[q]Afflizione\n Aumenta i danni inflitti da Anatema dell'Anima del 25% e la velocità a cui vengono inflitti del 20%.\n\n Consumare Notte Fonda attiva Fato Condiviso o Banchetto di Anime.\n\nDemonologia\n Aumenta i danni inflitti da Anatema dell'Anima del 25% e la velocità a cui vengono inflitti del 20%.\n\n Consumare Nucleo Demoniaco attiva Fato Condiviso o Banchetto di Anime."}
MultiLanguageSpellData['it'][449637] = {name = "Volontà di Sataiel", additional_info = "[q]Demonologia\n Aumenta i danni inflitti dagli Imp Selvaggi del 5%. Gli Imp Selvaggi che implodono hanno una probabilità aggiuntiva del 5% di fornire un Nucleo Demoniaco.\n\nAfflizione\n Aumenta la velocità a cui Corruzione infligge i danni del 25%. Tormento fornisce Notte Fonda."}
MultiLanguageSpellData['it'][449638] = {name = "Ombra di Morte", additional_info = "[q]Demonologia\n Il lancio di Evocazione: Tiranno Demoniaco viene potenziato dall'entità demoniaca interiore, fornendo 3 frammenti d'anima che contengono ciascuno un'Anima Succulenta.\n\nAfflizione\n Il lancio di Putrefazione d'Anima viene potenziato dall'entità demoniaca interiore, fornendo 3 frammenti d'anima che contengono ciascuno un'Anima Succulenta."}
