MultiLanguageSpellData['it'][450280] = {name = "[q3]Attrezzi da Conciatore Artigianali", additional_info = "3.5 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nIntuito dell'Artigiano (300), Polvere Cristallina (10), Pietra del Nulla (5), Lega di Grinfiaferro (7)\nReagenti Facoltativi:\nAccessori della Forgia (#317) , Autenticità dell'Artigiano (#346)\nMercante:\nLyrendal\nZona:\nDornogal\nCosto:\n150\n\n[q3]Attrezzi da Conciatore Artigianali\nSi vincola alla raccolta\nUnico equipaggiabile: Set di attrezzi (1)Accessorio di Conciatura\n[q2]+ 61 Parsimonia\n[q2]+ 61 Velocità di creazione\n[q2]Equipaggia: Aumenta la Competenza in Conciatura di Khaz Algar di 11.\n68"}
MultiLanguageSpellData['it'][450281] = {name = "[q3]Martello da Fabbro Artigianale", additional_info = "3.5 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nIntuito dell'Artigiano (300), Lingotto delle Profondità Risonanti , Lega di Grinfiaferro (5)\nReagenti Facoltativi:\nAccessori della Forgia (#317) , Personalizza statistiche di creazione (#352) , Autenticità dell'Artigiano (#346)\nSpecializzazione:\nMezzi di Produzione - Ferri del Mestiere\n\n[q3]Martello da Fabbro Artigianale\nSi vincola alla raccolta\nAttrezzo di Forgiatura\n[q2]+ 100 Attributo casuale 1\n[q2]Equipaggia: Aumenta la Competenza in Forgiatura di Khaz Algar di 18.\n68"}
MultiLanguageSpellData['it'][450282] = {name = "[q3]Attrezzi da Fabbro Artigianali", additional_info = "3.5 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nIntuito dell'Artigiano (300), Lingotto delle Profondità Risonanti , Lega di Grinfiaferro (4)\nReagenti Facoltativi:\nAccessori della Forgia (#317) , Autenticità dell'Artigiano (#346)\nSpecializzazione:\nMezzi di Produzione\n\n[q3]Attrezzi da Fabbro Artigianali\nSi vincola alla raccolta\nUnico equipaggiabile: Set di attrezzi (1)Accessorio di Forgiatura\n[q2]+ 61 Parsimonia\n[q2]+ 61 Velocità di creazione\n[q2]Equipaggia: Aumenta la Competenza in Forgiatura di Khaz Algar di 11.\n68\nRichiedeForgiatura di Khaz Algar\n(1)"}
MultiLanguageSpellData['it'][450283] = {name = "[q4]Martello del Maestro Terrigeno", additional_info = "3.5 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nLingotto delle Profondità Risonanti (2), Lega Caricata (10), Lega Santificata (10), Lega di Grinfiaferro (10)\nProfessione:\nForgiatura di Khaz Algar (100)\n\n[q4]Martello del Maestro Terrigeno\nSi vincola alla raccolta\n[q2]Usa: Ripara un'arma o un pezzo d'armatura a piastre che ci si è specializzati a riparare.\nRichiedeForgiatura di Khaz Algar\n(25)"}
MultiLanguageSpellData['it'][450291] = {name = "[q2]Martello per Riparazioni Nucleoforgiato", additional_info = "3.5 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nBismuto (10), Grinfiaferro (2)\nReagenti Facoltativi:\nAccessori della Forgia (#382)\nIstruttore delle Professioni:\nForgiatura di Khaz Algar (5)\nCosto:\n80\n\n[q2]Martello per Riparazioni Nucleoforgiato\n[q2]Usa: Ripara completamente un'arma o un pezzo d'armatura a piastre (si consuma con l'uso).\n70\nRichiedeForgiatura di Khaz Algar\n(1)"}
