MultiLanguageSpellData['it'][450373] = {name = "Non Guardarsi Indietro", additional_info = "[q]Ogni volta che Sentinella infligge danni a un nemico, fornisce uno scudo che assorbe danni subiti pari al 1.0% della tua salute massima, fino a un massimo del 10%."}
