MultiLanguageSpellData['it'][450379] = {name = "Impulso Rinvigorente", additional_info = "[q]Ogni volta che Sentinella infligge danni a un nemico, ha una probabilità di massimo il 15% di generare 5 focus.\n\n La probabilità si riduce a ogni Sentinella aggiuntiva applicata ai nemici attualmente in implosione."}
