MultiLanguageSpellData['it'][451609] = {name = "Bomba Ragnatela", additional_info = "Portata illimitata\nIstantaneo\n[q]La Tessigrovigli Takazj lancia ragnatele esplosive contro i personaggi, infliggendo 20 danni da natura a tutti i personaggi entro 10 m.\n\n Se più di un personaggio si trova nell'area d'effetto, tutti vengono legati insieme da Ragnatele Vincolanti , che ne riduce la velocità di movimento del 20 %.\n\n Se i personaggi legati si allontanano per più di 30 m, o se Anub'arash vi carica attraverso, la ragnatela si rompe e dissolve le Ragnatele Vincolanti ."}
MultiLanguageSpellData['it'][451610] = {name = "Bomba Ragnatela", additional_info = "Portata illimitata\nIstantaneo\n[q]Takazj lancia nodi di filamenti appiccicosi in tutta la camera, riducendo la velocità di movimento dei personaggi del 20% e infliggendo 345379 danni fisici ogni 1 s nell'area d'effetto.\n\n Il nodo centrale erutta, quando viene toccato, infliggendo 1732248 danni da natura ai personaggi entro 10 m e legando insieme due personaggi con Ragnatele Vincolanti .\n\n Se Anub'arash carica attraverso le Ragnatele Vincolanti, diventa Intrappolato."}
MultiLanguageSpellData['it'][451611] = {name = "Bersaglio Bomba di Fuoco", additional_info = "Portata di 100 m\nIstantaneo\n[q]Takazj lancia nodi di filamenti appiccicosi in tutta la camera, riducendo la velocità di movimento dei personaggi del 20% e infliggendo 345379 danni fisici ogni 1 s nell'area d'effetto.\n\n Il nodo centrale erutta, quando viene toccato, infliggendo 1732248 danni da natura ai personaggi entro 10 m e legando insieme due personaggi con Ragnatele Vincolanti .\n\n Se Anub'arash carica attraverso le Ragnatele Vincolanti, diventa Intrappolato."}
