MultiLanguageSpellData['it'][452402] = {name = "Impeto Demoniaco", additional_info = "[q]Rovina\n Metamorfosi Demoniaca aumenta la furia generata da Morso del Demone di 15.\n\n Quando la Forma Demoniaca è attiva, il primo lancio di ogni abilità potenziata attiva Impeto Demoniaco, la cui scarica di vilenergia infligge ([330% of Attack Power]) danni da fuoco ai nemici vicini. Danni ridotti oltre 8 bersagli.\n\nVendetta\n Metamorfosi Demoniaca potenzia significativamente Fendente d'Anima e Bomba Spirituale.\n\n Quando la Forma Demoniaca è attiva, il primo lancio di ogni abilità potenziata attiva Impeto Demoniaco, la cui scarica di vilenergia infligge ([330% of Attack Power]) danni da fuoco ai nemici vicini. Danni ridotti oltre 8 bersagli."}
MultiLanguageSpellData['it'][452403] = {name = "Ondata di Spossatezza", additional_info = "[q]Nova del Caos riduce la velocità di movimento dei nemici del 60% e ne riduce le velocità d'attacco e di lancio d'incantesimi del 15% per 5 s dopo che l'effetto di stordimento è terminato."}
MultiLanguageSpellData['it'][452404] = {name = "In Cerca di Rabbia", additional_info = "[q]Aumenta la velocità di movimento del 1% per 10 furia."}
MultiLanguageSpellData['it'][452405] = {name = "Odio Concentrato", additional_info = "[q]Aumenta i danni inflitti da Impeto Demoniaco del 50% quando colpisce un bersaglio singolo.\n\n Ogni bersaglio aggiuntivo riduce questo bonus del 10%."}
MultiLanguageSpellData['it'][452406] = {name = "Fiamme di Dolore", additional_info = "[q]Il 5% di tutti i danni non da fuoco subiti viene subito invece come danni da fuoco in 6 s.\n\n Danni da fuoco subiti ridotti del 10%."}
MultiLanguageSpellData['it'][452407] = {name = "Lacerazione d'Anima Migliorata", additional_info = "[q]Aumenta il ritorno vitale fornito da Lacerazione d'Anima del 2% e del 2% aggiuntivo quando Metamorfosi Demoniaca è attiva."}
MultiLanguageSpellData['it'][452408] = {name = "Lame Brucianti", additional_info = "[q]Rovina\n Le lame bruciano di vilenergia e fanno sì che Assalto del Caos, Lancio Lama e gli attacchi automatici infliggano il 50% di danni aggiuntivi come danni da fuoco in 6 s.\n\nVendetta\n Le lame bruciano di vilenergia e fanno sì che Fendente d'Anima, Lancio Lama e gli attacchi automatici infliggano il 40% di danni aggiuntivi come danni da fuoco in 6 s."}
MultiLanguageSpellData['it'][452409] = {name = "Trasformazione Violenta", additional_info = "[q]Rovina\n Quando si attiva Metamorfosi Demoniaca, i tempi di recupero di Sigillo della Fiamma e Rogo Rovente si azzerano istantaneamente.\n\nVendetta\n Quando si attiva Metamorfosi Demoniaca, i tempi di recupero di Sigillo della Fiamma e Vildevastazione si azzerano istantaneamente."}
MultiLanguageSpellData['it'][452410] = {name = "Tormento Persistente", additional_info = "[q]Rovina\n Gli effetti della Forma Demoniaca persistono in uno stato indebolito, aumentando i danni inflitti da Assalto del Caos e Lame Danzanti del 15% e la celerità del 5%.\n\nVendetta\n Gli effetti della Forma Demoniaca persistono in uno stato indebolito, aumentando la salute massima del 5% e l'armatura del 20%."}
MultiLanguageSpellData['it'][452411] = {name = "Furia Senza Limiti", additional_info = "[q]Aumenta la furia massima di 50."}
MultiLanguageSpellData['it'][452412] = {name = "Studente della Sofferenza", additional_info = "[q]Sigillo della Fiamma attiva Studente della Sofferenza, che aumenta la maestria del (8 * $mas)% e genera 5 furia ogni 2 s per 6 s."}
MultiLanguageSpellData['it'][452413] = {name = "Vincolafiamma", additional_info = "[q]Aumenta il raggio di Rogo Rovente di 2 m e i danni critici aggiuntivi che infligge del 50%."}
MultiLanguageSpellData['it'][452414] = {name = "Mostro Nascente", additional_info = "[q]Aumenta l'Agilità del 8% quando non si è in Forma Demoniaca."}
MultiLanguageSpellData['it'][452415] = {name = "Intensità Demoniaca", additional_info = "[q]Rovina\n Attivare Metamorfosi Demoniaca potenzia significativamente Raggio Oculare, Rogo Rovente e Sigillo della Fiamma.\n\n Aumenta i danni inflitti da Impeto Demoniaco del 10 % per ogni volta che si è attivato durante la Forma Demoniaca precedente.\n\nVendetta\n Attivare Metamorfosi Demoniaca potenzia significativamente Vildevastazione, Rogo Rovente e Sigillo della Fiamma.\n\n Aumenta i danni inflitti da Impeto Demoniaco del 10 % per ogni volta che si è attivato durante la Forma Demoniaca precedente."}
