MultiLanguageSpellData['it'][453250] = {name = "Cristallizzazione", additional_info = "Cristallizzazione Livello 80\n[q0][Item Effect]Istantaneo\n[q]Aumenta [[Primary Stat]] di 733 per 1 ora. Runa del Potenziamento."}
MultiLanguageSpellData['it'][453251] = {name = "Bomba Vivente", additional_info = "Portata illimitata\nIstantaneo\n[q]Il bersaglio diventa una Bomba Vivente, subendo 4 danni da fuoco in 2 s, per poi esplodere, infliggendo ([26.8% of Spell Power]) danni da fuoco aggiuntivi a se stesso e danni ridotti a tutti gli altri nemici entro 10 m.\n\n Gli altri nemici colpiti dall'esplosione diventano a loro volta delle Bombe Viventi, ma non diffondono più l'effetto."}
