MultiLanguageSpellData['it'][454389] = {name = "Evocazione: Biancachioma", additional_info = "Istantaneo\n[q]Consumare rune ha una probabilità di richiamare in aiuto un Cavaliere per 10 s.\n\nMograine\n Lancia sulla propria posizione un effetto di Morte e Distruzione che lo segue.\n\nBiancachioma\n Lancia Non Morte sul bersaglio, infliggendo ([9.15376% of Attack Power]) danni da ombrogelo per accumulo ogni 3 s per 24 s. Ogni volta che Non Morte infligge danni, si accumula. L'effetto non può essere rinnovato.\n\nCacciatroll\n Lancia Catene di Ghiaccio sul bersaglio, riducendone la velocità di movimento del 40% e aumentando i danni da te inflitti a quel bersaglio del 5% per 8 s.\n\nNazgrim\n Finché Nazgrim è attivo, fornisce Conquista Apocalittica, che aumenta la Forza del 5%."}
MultiLanguageSpellData['it'][454390] = {name = "Evocazione: Cacciatroll", additional_info = "Istantaneo\n[q]Consumare rune ha una probabilità di richiamare in aiuto un Cavaliere per 10 s.\n\nMograine\n Lancia sulla propria posizione un effetto di Morte e Distruzione che lo segue.\n\nBiancachioma\n Lancia Non Morte sul bersaglio, infliggendo ([9.15376% of Attack Power]) danni da ombrogelo per accumulo ogni 3 s per 24 s. Ogni volta che Non Morte infligge danni, si accumula. L'effetto non può essere rinnovato.\n\nCacciatroll\n Lancia Catene di Ghiaccio sul bersaglio, riducendone la velocità di movimento del 40% e aumentando i danni da te inflitti a quel bersaglio del 5% per 8 s.\n\nNazgrim\n Finché Nazgrim è attivo, fornisce Conquista Apocalittica, che aumenta la Forza del 5%."}
MultiLanguageSpellData['it'][454391] = {name = "Potere Illimitato", additional_info = "[q]Potenziamento\n Consumare accumuli di Arma del Maelstrom aumenta la celerità del 1% per 15 s.\n\n Applicazioni multiple potrebbero sovrapporsi.\n\nElementale\n Consumare maelstrom aumenta la celerità del 1% per 15 s.\n\n Applicazioni multiple potrebbero sovrapporsi."}
MultiLanguageSpellData['it'][454392] = {name = "Evocazione: Nazgrim", additional_info = "Istantaneo\n[q]Consumare rune ha una probabilità di richiamare in aiuto un Cavaliere per 10 s.\n\nMograine\n Lancia sulla propria posizione un effetto di Morte e Distruzione che lo segue.\n\nBiancachioma\n Lancia Non Morte sul bersaglio, infliggendo ([9.15376% of Attack Power]) danni da ombrogelo per accumulo ogni 3 s per 24 s. Ogni volta che Non Morte infligge danni, si accumula. L'effetto non può essere rinnovato.\n\nCacciatroll\n Lancia Catene di Ghiaccio sul bersaglio, riducendone la velocità di movimento del 40% e aumentando i danni da te inflitti a quel bersaglio del 5% per 8 s.\n\nNazgrim\n Finché Nazgrim è attivo, fornisce Conquista Apocalittica, che aumenta la Forza del 5%."}
