MultiLanguageSpellData['it'][454426] = {name = "Sventura Erogata", additional_info = "[q]Aumenta i danni inflitti quando il lancio della Moneta Vincolafato mostra croce del 30% se non ci sono altri nemici vicino al bersaglio.\n\n Ogni nemico vicino aggiuntivo riduce questo bonus del 6%."}
MultiLanguageSpellData['it'][454428] = {name = "Fine Profetica", additional_info = "[q]Quando la Moneta Vincolafato lanciata mostra la stessa faccia per la settima volta consecutiva, aumenta l'Agilità del 7% finché non si lascia il combattimento per 10 s. Se questo effetto è già attivo, infligge invece ([420% of Attack Power]) danni cosmici al bersaglio."}
MultiLanguageSpellData['it'][454429] = {name = "Destini Intrecciati", additional_info = "[q]Assassinio\n Destini Intrecciati duplica il 30% dei danni critici inflitti da Affondo Venefico come danni cosmici a 2 nemico vicino aggiuntivo. Se non ci sono bersagli vicini aggiuntivi, duplica invece il 30% sul bersaglio primario.\n\nFuorilegge\n Destini Intrecciati duplica il 30% dei danni critici inflitti da Eliminazione come danni cosmici a 2 nemico vicino aggiuntivo. Se non ci sono bersagli vicini aggiuntivi, duplica invece il 30% sul bersaglio primario."}
MultiLanguageSpellData['it'][454430] = {name = "Doppia Condanna", additional_info = "[q]Il primo lancio della Moneta Vincolafato dopo che Furtività è terminata lancia due monete che mostrano sempre lo stesso risultato."}
MultiLanguageSpellData['it'][454431] = {name = "[q4]Borsa Recisa", additional_info = "2 s di lancio 2\nReagenti:\nNastro Decorativo (2), Rotolo di Tessivespro (5), Rotolo di Tessialba (5)\nReagenti Facoltativi:\nFilo per Ricami (#333)\nSpecializzazione:\nTessuti di Qualità (25)\n\n[q4]Borsa Recisa\nSi vincola alla raccolta\nUnico\nSacca da 36 scomparti\n[q2]Equipaggia: Aumenta la resa massima della Sbrogliatura di Khaz Algar di 1.\n\n [ L'effetto all'equipaggiamento richiede la Sartoria di Khaz Algar 1 ][ L'effetto all'equipaggiamento richiede la Sartoria di Khaz Algar 1 ]68\n[q]\"Un contenitore cucito dai maestri artigiani della Tessitrice, capace di massimizzare il valore di tessuti elusivi come il Tessialba e il Tessivespro.\""}
MultiLanguageSpellData['it'][454432] = {name = "Marcia Inesorabile", additional_info = "[q]La velocità di movimento non può essere ridotta a meno del 70% della velocità di movimento normale quando i lanci della Moneta Vincolafato hanno una serie attiva di almeno 2 lanci che mostrano la stessa faccia."}
MultiLanguageSpellData['it'][454433] = {name = "Arrivo della Morte", additional_info = "[q]Assassinio\n Permette di lanciare Passo nell'Ombra una seconda volta entro 3 s senza attivare il tempo di recupero, ma il tempo di recupero totale aumenta di 5 s.\n\nFuorilegge\n Permette di lanciare Rampino una seconda volta entro 3 s senza attivare il tempo di recupero, ma il tempo di recupero totale aumenta di 5 s."}
MultiLanguageSpellData['it'][454434] = {name = "Fine Inevitabile", additional_info = "[q]Fuorilegge\n Sangue Freddo fornisce benefici alle successive 2 abilità ma si applica solo a Eliminazione. Le Monete Vincolafato lanciate da queste abilità mostrano sempre lo stesso risultato dell'ultimo lancio.\n\nAssassinio\n Sangue Freddo fornisce benefici alle successive 2 abilità ma si applica solo ad Affondo Venefico. Le Monete Vincolafato lanciate da queste abilità mostrano sempre lo stesso risultato dell'ultimo lancio."}
MultiLanguageSpellData['it'][454435] = {name = "Destino Scritto", additional_info = "[q]Fuorilegge\n Assalto Funesto ha una probabilità aggiuntiva del 5% di colpire una volta aggiuntiva e le Monete Vincolafato lanciate hanno una probabilità aggiuntiva del 5% di mostrare la stessa faccia dell'ultimo lancio.\n\nAssassinio\n Gli effetti di veleno sulle armi hanno una probabilità aggiuntiva del 5% e le Monete Vincolafato lanciate hanno una probabilità aggiuntiva del 5% di mostrare la stessa faccia dell'ultimo lancio."}
MultiLanguageSpellData['it'][454436] = {name = "Calpestamento", additional_info = "Portata di 100 m\nIstantaneo\n[q]Carica un nemico casuale, infliggendo 11025 danni da ombra a tutti i personaggi colpiti lungo la traiettoria, stordendoli per 10 s."}
MultiLanguageSpellData['it'][454437] = {name = "Carica d'Azerite", additional_info = "Istantaneo\n[q]Bersaglio di Carica d'Azerite!"}
MultiLanguageSpellData['it'][454438] = {name = "Carica d'Azerite", additional_info = "Portata di 100 m\n3 s di lancio\n[q]Carica verso il bersaglio nemico e genera un'esplosione di energia d'Azerite, infliggendo 4134 danni da arcano istantaneamente e 1102 danni da arcano aggiuntivi ogni 1 s per 5 s a tutti i nemici entro 8 m dal punto d'impatto."}
MultiLanguageSpellData['it'][454439] = {name = "Carica d'Azerite", additional_info = "Portata di 100 m\nIstantaneo\n[q]Carica verso il bersaglio nemico e genera un'esplosione di energia d'Azerite, infliggendo 4134 danni da arcano istantaneamente e 1102 danni da arcano aggiuntivi ogni 1 s per 5 s a tutti i nemici entro 8 m dal punto d'impatto."}
MultiLanguageSpellData['it'][454440] = {name = "Vomito Puzzolente", additional_info = "Portata di 100 m\n2 s di lancio\n[q]Infligge 1654 danni da natura ai nemici istantaneamente e 1102 danni da natura aggiuntivi ogni 2 s per 12 s."}
MultiLanguageSpellData['it'][454441] = {name = "Diventare un Pescatore Algari", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Diventare un pescatore è facile!\n\n Prendi la canna da pesca e lancia la lenza per pescare i tanti segreti che Khaz Algar ha da offrire.\n\n I pesci catturati e le pozze di pesca scoperte compaiono qui, nelle tue fidate Cronache di Pesca. Questi registri riportano tutti i dettagli dei pesci più rari e forniscono indicazioni su dove trovarli!\nProfessione:\nPesca (1)"}
MultiLanguageSpellData['it'][454442] = {name = "Tu e la Competenza in Pesca", additional_info = "Portata di 5 m\n3.2 s di lancio\n[q]Man mano che la tua capacità di pescare il pesce perfetto migliora, anche la tua Competenza in Pesca aumenta!\n\n Migliorare la Competenza in Pesca fa la differenza tra pescare un vecchio scarpone o un prezioso pesce da trofeo.\nProfessione:\nPesca (25)"}
MultiLanguageSpellData['it'][454443] = {name = "Spigola di Fiume Quieta", additional_info = "Istantaneo\n[q]Scaglie scintillanti di smeraldo ricoprono questo pesce altrimenti banale. Facile da trovare e appetitosa, la Spigola di Fiume Quieta è un ingrediente base di ogni piatto di pesce.\n\nSpeciale:\n\n Filetto Fresco\n\n Recuperare questo pesce con la competenza in Cucina può produrre una certa quantità di Filetto Fresco.\n\nAree in cui si può trovare questo pesce:\n\n - Isola di Dorn\n - Profondità Risonanti\n - Isola delle Sirene\n\nPozze di Pesca:\n\n - Increspatura sulla Superficie Calma\n - Banco di Spigole di Fiume\nProfessione:\nPesca"}
