MultiLanguageSpellData['it'][456575] = {name = "Sprintapasso", additional_info = "Sprintapasso Livello 80\n[q0][Item Effect]Istantaneo\n[q]Rigenera ( 937500 / 5 * 20) mana in 20 s. Devi sederti per bere.\n\n Sprintapasso\n Se bevi per almeno 10 s guadagni 167 velocità di movimento e l'abilità di camminare sull'acqua per 10 min."}
MultiLanguageSpellData['it'][456576] = {name = "Sorsata di Proteine", additional_info = "Sorsata di Proteine Livello 80\n[q0][Item Effect]Istantaneo\n[q]Rigenera ( 375000 / 5 * 20) mana in 20 s. Devi sederti per bere.\n\n Ben Nutrito\n Se mangi per almeno 10 s diventi Ben Nutrito e guadagni [ 470 * (0.7)] nella tua statistica secondaria più bassa, aumentando anche le dimensioni del 1%, per 15 min."}
