MultiLanguageSpellData['it'][456586] = {name = "Percezione Algari", additional_info = "[q0][Item Effect]Portata di 12 - 15 m\nIstantaneo\n[q]Rilancia il pesce in acqua per aumentare la Percezione di 45 per 30 s.\n\n Lanciare più pesci estende la durata del beneficio fino a un massimo di 5 min."}
MultiLanguageSpellData['it'][456587] = {name = "Esca Reale", additional_info = "[q0][Item Effect]Portata di 12 - 15 m\nIstantaneo\n[q]Rilancia questo pesce in acqua per ottenere 1 accumulo di Esca Reale, che protegge le acque intorno dal Pesce Ghoul corrotto e aumenta le probabilità di pescare un Pesce Lanterna della Regina per 30 s.\n\n Lanciare più Pseudocromidi Regali estende la durata del beneficio fino a un massimo di 10 min."}
MultiLanguageSpellData['it'][456588] = {name = "Isola di Dorn", additional_info = "Istantaneo\n[q]Competenza consigliata: 1\n\n Mari calmi e condizioni familiari rendono quest'area perfetta per i pescatori che desiderano fare pratica prima di scendere più in profondità a Khaz Algar.\n\n Pozze disponibili in questa zona:\n - Stagnolustro\n - Tesoro a Riva\n - Banco di Lucerne\n - Pozzamarcia Putrescente\n - Increspatura sulla Superficie Calma\n - Banco di Spigole di Fiume\n - Banco di Persici Cruenti\nProfessione:\nPesca (1)"}
MultiLanguageSpellData['it'][456589] = {name = "Profondità Risonanti", additional_info = "Istantaneo\n[q]Competenza consigliata: 125\n\n Un sistema di caverne benedetto dal connubio tra industria e adattamento. I fiumi qui pullulano di ogni tipo di forma di vita, sia in superficie che in profondità.\n\n Pozze disponibili in questa zona:\n - Stagnolustro\n - Increspatura sulla Superficie Calma\n - Banco di Spigole di Fiume\n - Torrente di Grandocchio\n - Tesoro delle Profondità Galleggiante\nProfessione:\nPesca (75)"}
MultiLanguageSpellData['it'][456590] = {name = "Precipizi Sacri", additional_info = "Istantaneo\n[q]Competenza consigliata: 225\n\n Un'area sorprendentemente ricca di ogni genere di forma di vita. Voragini profonde e vasti fiumi sotterranei la rendono un crocevia per i pescatori che vogliono mettere alla prova le proprie abilità.\n\n Pozze disponibili in questa zona:\n - Increspatura sulla Superficie Calma\n - Stagnolustro\n - Torrente di Grandocchio\n - Tesoro delle Profondità Galleggiante\n - Sversamento di Icore Infuso\n - Sussurri delle Profondità\n - Increspatura Regale\n - Sangue in Acqua\nProfessione:\nPesca (150)"}
MultiLanguageSpellData['it'][456591] = {name = "Azj-Kahet", additional_info = "Istantaneo\n[q]Competenza consigliata: 375\n\n Acque rade piene dell'icore di stranezze di ogni tipo. Particolarmente impegnative da attraversare per i pescatori non esperti.\n\n Pozze disponibili in questa zona:\n - Increspatura sulla Superficie Calma\n - Stagnolustro\n - Sversamento di Icore Infuso\n - Increspatura Regale\n - Banco di Squali dei Bassifondi\n - Sussurri delle Profondità\nProfessione:\nPesca (225)"}
