MultiLanguageSpellData['it'][456939] = {name = "Atrofia Rovente", additional_info = "[q]Aumenta i danni inflitti da Combustione dell'Ombra del 20%. Aumenta la probabilità di critico di Combustione dell'Ombra del 50% aggiuntivo quando infligge danni a un bersaglio con il 30% o meno della salute massima."}
