MultiLanguageSpellData['it'][456957] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo di Punta di Freccia di Porcellana\n[q]Gli incantesimi e le abilità di Brann hanno una probabilità di indebolire i nemici, aumentandone la probabilità di subire un colpo critico del 30 % per 5 s.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456958] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo della Forza Bruta\n[q]Al comando di Brann, saltare su di lui fa sì che lui lanci i personaggi sui nemici, respingendoli indietro e infliggendo significativi danni fisici suddivisi tra loro. Può verificarsi fino a 2 volte di seguito.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456959] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo della Madre Terra\n[q]Gli incantesimi e le abilità di Brann hanno una probabilità di risvegliare l'idolo, proteggendo un personaggio ferito con uno scudo pari al 30 % della salute mancante.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456960] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo di Ferro Indistruttibile\n[q]Quando un personaggio ha il 40 % o meno della salute massima durante un combattimento, l'idolo si attiva, infliggendo moderati danni fisici ai nemici vicini e provocandoli per 6 s. Può verificarsi solo una volta ogni 2 min.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456961] = {name = "Ben Nutrito", additional_info = "Ben Nutrito Livello 80\nIstantaneo\n[q]Aumenta le statistiche e fornisce effetti aggiuntivi in base al cibo di Khaz Algar consumato."}
MultiLanguageSpellData['it'][456962] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo Toccato dalla Luce\n[q]Quando un personaggio usa un'abilità difensiva con un tempo di recupero di almeno 30 s, l'idolo si attiva e lo cura del ( 200 / 100)% della salute massima ogni 1 s per 10 s.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456963] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo della Volontà Finale\n[q]Durante il combattimento, Brann designa un personaggio per indirizzare i colpi per 4 s prima di sparare verso la sua posizione, infliggendo ingenti danni fisici al primo nemico colpito.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456965] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Amorfa\n[q]Quando entrano in combattimento, i personaggi ottengono Massiccio o Miniatura finché il combattimento non termina.\n\nMassiccio\nAumenta le dimensioni del 20%, la salute massima del 10% e i danni inflitti e le cure fornite del 6%.\n\n Miniatura\nRiduce le dimensioni del 20%, aumenta la velocità di movimento del 10% e aumenta la celerità del 6%.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456966] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia del Tempo Perduto\n[q]Gli incantesimi e le abilità di Brann hanno una probabilità di creare una scarica di energia, distorcendo il flusso temporale per tutti i personaggi vicini del 20 % per 12 s.\n\n Le velocità di lancio d'incantesimi, di movimento, d'attacco, di recupero e degli effetti periodici vengono tutte distorte dal tempo.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456967] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Cercatrice Antica\n[q]Quando Brann usa la Raccolta Attrezzi , c'è una probabilità del 35 % di dissotterrare un potente manufatto che fornisce al gruppo un potente Dono.\n\n Raccolta Attrezzi\nBrann usa i suoi attrezzi di raccolta per aiutare i personaggi a trovare oro, erbe, minerali, pesci, pelli e tesori aggiuntivi.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456968] = {name = "Rinfresco", additional_info = "Rinfresco Livello 80\n[q0][Item Effect]Istantaneo\n[q]Rigenera ( 1350000 / 5 * 20) salute e ( 675000 / 5 * 20) mana in 20 s. Devi sederti per mangiare.\n\n Ben Nutrito\n Se mangi per almeno 10 s diventi Ben Nutrito e guadagni ( 470 * .7) indice di critico per 1 ora."}
MultiLanguageSpellData['it'][456969] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Necrotica Senza Vita\n[q]L'idolo attinge all'energia empia per evitare che i personaggi subiscano danni fatali, curandoli invece di un ammontare pari al 100 % della loro salute massima e trasformandoli in Non Morti.\n\n Da Non Morti, i personaggi non possono essere curati, perdono il 11 % della salute massima ogni 1 s e forniscono cure e infliggono danni aumentati del 8 %.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456970] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia della Senzienza\n[q]Quando una Trappola d'Acciaio viene attivata, c'è una probabilità che Brann lanci una trappola aggiuntiva.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456971] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia di Sangue di Zekvir\n[q]Quando Brann è in combattimento, talvolta una bestia di sangue gli si attacca addosso e lancia pezzetti di se stessa verso i personaggi vicini, fornendo Benedizione Macchiata di Sangue a chi li calpesta.\n\n Benedizione Macchiata di Sangue\nAumenta i danni inflitti e le cure fornite del 2% e riduce la salute massima del 5% per 1 min.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456972] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Ottimizzata\n[q]Quando non si è in combattimento, la velocità di movimento del gruppo aumenta del 20 %. Quando si entra in combattimento, la celerità del gruppo aumenta del 10 % per 8 s.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456973] = {name = "Eruzione di Spine", additional_info = "Portata di 50 m\n3 s di lancio\n[q]L'incantatore si immerge e poi fuoriesce, trascinando con sé degli spuntoni che infliggono 25 danni fisici ai personaggi colpiti."}
MultiLanguageSpellData['it'][456975] = {name = "Avatar della Distruzione", additional_info = "[q]Consumare Rituale della Rovina evoca un Demonio Supremo per 8 s.\n\n Evocazione: Signore dei Demoni\nFornisce 1 scheggia di frammento d'anima ogni 1 s e lancia Dardo del Caos al 80% dell'efficacia contro il bersaglio del proprio evocatore."}
