MultiLanguageSpellData['it'][456979] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo di Punta di Freccia di Porcellana\n[q]Gli incantesimi e le abilità di Brann hanno una probabilità di indebolire i nemici, aumentandone la probabilità di subire un colpo critico del 40 % per 5 s.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456980] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo della Forza Bruta\n[q]Al comando di Brann, saltare su di lui fa sì che lui lanci i personaggi sui nemici, respingendoli indietro e infliggendo significativi danni fisici suddivisi tra loro. Può verificarsi fino a 2 volte di seguito.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456981] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo della Madre Terra\n[q]Gli incantesimi e le abilità di Brann hanno una probabilità di risvegliare l'idolo, proteggendo un personaggio ferito con uno scudo pari al 50% della salute mancante.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456982] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo di Ferro Indistruttibile\n[q]Quando un personaggio ha il 40% o meno della salute massima durante un combattimento, l'idolo si attiva, infliggendo moderati danni fisici ai nemici vicini e provocandoli per 8 s. Può verificarsi solo una volta ogni 2 min.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456983] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo Toccato dalla Luce\n[q]Quando un personaggio usa un'abilità difensiva con un tempo di recupero di almeno 30 s, l'idolo si attiva e lo cura del ( 300 / 100)% della salute massima ogni 1 s per 10 s.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456984] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nIdolo della Volontà Finale\n[q]Durante il combattimento, Brann designa un personaggio per indirizzare i colpi per 4 s prima di sparare verso la sua posizione, infliggendo straordinari danni fisici al primo nemico colpito.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456985] = {name = "Decimazione", additional_info = "[q]I colpi critici inferti con abilità a bersaglio singolo hanno una probabilità di azzerare il tempo di recupero di Fuoco dell'Anima e di ridurre il tempo di lancio del successivo Fuoco dell'Anima del 80%."}
MultiLanguageSpellData['it'][456986] = {name = "Protocollo di Purificazione", additional_info = "Portata di 300 m\nIstantaneo\n[q]L'incantatore richiama una raffica di meteore fuse, ciascuna delle quali infligge 6 danni da fuoco ai personaggi entro 8 m."}
MultiLanguageSpellData['it'][456987] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Amorfa\n[q]Quando entrano in combattimento, i personaggi ottengono Massiccio o Miniatura finché il combattimento non termina.\n\n Massiccio\nAumenta le dimensioni del 20%, la salute massima del 15% e i danni inflitti e le cure fornite del 9%.\n\n Miniatura\nRiduce le dimensioni del 20%, aumenta la velocità di movimento del 15% e aumenta la celerità del 9%.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456988] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia del Tempo Perduto\n[q]Gli incantesimi e le abilità di Brann hanno una probabilità di creare una scarica di energia, distorcendo il flusso temporale per tutti i personaggi vicini del 25% per 12 s.\n\n Le velocità di lancio d'incantesimi, di movimento, d'attacco, di recupero e degli effetti periodici vengono tutte distorte dal tempo.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456989] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Cercatrice Antica\n[q]Quando Brann usa la Raccolta Attrezzi , c'è una probabilità del 35 % di dissotterrare fino a 2 potenti manufatti che forniscono al gruppo un potente Dono.\n\n Raccolta Attrezzi\nBrann usa i suoi attrezzi di raccolta per aiutare i personaggi a trovare oro, erbe, minerali, pesci, pelli e tesori aggiuntivi.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456990] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Necrotica Senza Vita\n[q]L'idolo attinge all'energia empia per evitare che i personaggi subiscano danni fatali, curandoli invece di un ammontare pari al 100 % della loro salute massima e trasformandoli in Non Morti.\n\n Da Non Morti, i personaggi non possono essere curati, perdono il 7 % della salute massima ogni 1 s e forniscono cure e infliggono danni aumentati del 10 %.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456991] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia della Senzienza\n[q]Quando una Trappola d'Acciaio viene attivata, c'è una probabilità che Brann lanci una trappola aggiuntiva.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456992] = {name = "Incandescenza", additional_info = "Portata di 100 m\nIstantaneo\n[q]Ogni carica di potere sacro consumata ha una probabilità del 5% di attivare [ Martello Divino / Consacrazione], infliggendo ([36% of Attack Power]) danni da sacro a massimo 5 nemici nell'area d'effetto."}
MultiLanguageSpellData['it'][456993] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia di Sangue di Zekvir\n[q]Quando Brann è in combattimento, talvolta una bestia di sangue gli si attacca addosso e lancia pezzetti di se stessa verso i personaggi vicini, fornendo Benedizione Macchiata di Sangue a chi li calpesta.\n\n Benedizione Macchiata di Sangue\nAumenta i danni inflitti e le cure fornite del 2% e riduce la salute massima del 4% per 1 min.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][456994] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nReliquia Ottimizzata\n[q]Quando non si è in combattimento, la velocità di movimento del gruppo aumenta del 30 %. Quando si entra in combattimento, la celerità del gruppo aumenta del 15 % per 8 s.\n\nHai già questo Reperto nella tua collezione."}
