MultiLanguageSpellData['it'][457052] = {name = "Marchio dell'Inseguitore della Morte", additional_info = "[q]Scaltrezza\n Lanciare Assalto d'Ombra in modalità furtiva o Danza dell'Ombra applica 3 accumulo di Marchio dell'Inseguitore della Morte al bersaglio. Consumare 5 o più punti combo con attacchi contro un bersaglio Marchiato consuma 1 accumulo di Marchio dell'Inseguitore della Morte per infliggere ([120% of Attack Power]) danni da piaga e aumentare i danni inflitti dal successivo lancio di del 50%.\n È possibile avere un solo bersaglio Marchiato alla volta.\n\nAssassinio\n Lanciare Imboscata in modalità furtiva applica 3 accumulo di Marchio dell'Inseguitore della Morte al bersaglio. Consumare 5 o più punti combo con attacchi contro un bersaglio Marchiato consuma 1 accumulo di Marchio dell'Inseguitore della Morte per infliggere ([120% of Attack Power]) danni da piaga e aumentare i danni inflitti dal successivo lancio di Imboscata o Mutilazione del 50%.\n È possibile avere un solo bersaglio Marchiato alla volta."}
MultiLanguageSpellData['it'][457054] = {name = "Battuta di Caccia", additional_info = "[q]Gli attacchi automatici contro i bersagli Marchiati infliggono ([25% of Attack Power]) danni da piaga aggiuntivi."}
MultiLanguageSpellData['it'][457055] = {name = "Unico Obiettivo", additional_info = "[q]I danni inflitti a bersagli che non sono stati Marchiati da te infliggono il 5% di danni da piaga aggiuntivi al bersaglio Marchiato."}
MultiLanguageSpellData['it'][457056] = {name = "Oscurità Persistente", additional_info = "[q]Scaltrezza\n Quando l'effetto di Lame d'Ombra termina, i danni da ombra inflitti aumentano del 30% per 30 s.\n\nAssassinio\n Quando l'effetto di Stigma Letale termina, i danni da natura inflitti aumentano del 30% per 30 s."}
MultiLanguageSpellData['it'][457057] = {name = "Calcaombre", additional_info = "[q]Consumare l'ultimo Marchio dell'Inseguitore della Morte sul bersaglio riduce il tempo di recupero di Passo nell'Ombra di 3 s."}
MultiLanguageSpellData['it'][457058] = {name = "Notte Cupa", additional_info = "[q]Assassinio\n Quando si consuma l'ultimo Marchio dell'Inseguitore della Morte su un bersaglio o il bersaglio muore, si rigenera 40 energia e il successivo lancio di Affondo Venefico con il massimo di punti combo è sempre un colpo critico, infligge il 60% di danni aggiuntivi e applica 3 accumulo di Marchio dell'Inseguitore della Morte al bersaglio.\n\nScaltrezza\n Quando si consuma l'ultimo Marchio dell'Inseguitore della Morte su un bersaglio o il bersaglio muore, si rigenera 40 energia e il successivo lancio di Sventramento con il massimo di punti combo è sempre un colpo critico, infligge il 60% di danni aggiuntivi e applica 3 accumulo di Marchio dell'Inseguitore della Morte al bersaglio."}
