MultiLanguageSpellData['it'][460443] = {name = "Dardo Fulminante", additional_info = "Portata di 40 m\n1.4 s di lancio\n[q]Lancia un fulmine contro il bersaglio, infliggendo 276387 danni da natura.\n\nGenera 8 maelstrom."}
