MultiLanguageSpellData['it'][460468] = {name = "Imposizione della Provocazione", additional_info = "Portata di 40 m\n{Istantaneo} {1.5 s di recupero}\n[q]Provoca il bersaglio, inducendolo ad attaccarti. Non ha effetto se il bersaglio ti sta già attaccando."}
MultiLanguageSpellData['it'][460469] = {name = "Piuma di Corvo della Tempesta Caricata", additional_info = "[q0][Item Effect]Portata di 15 m\n{Istantaneo} {1.5 min di recupero}\n[q]Tenere la piuma per [1.0][1] s permette di colpire con la potenza della tempesta, schiantandosi sulla posizione bersaglio e infliggendo ( 1 * 3166 ) danni da natura suddivisi tra i nemici vicini."}
MultiLanguageSpellData['it'][460472] = {name = "Colpo Grosso", additional_info = "Portata di 100 m\n{2.5 s di lancio} {3 s di recupero}\n[q]Il Bandito con un Braccio Solo colpisce il terreno con il suo grosso braccio, infliggendo 50310521 danni fisici al bersaglio e aumentando i danni a lui inflitti da Colpo Grosso del 750% per 30 s. Si accumula.\n\n Inoltre, Colpo Grosso lascia dietro di sé un Campo Folgorante ."}
MultiLanguageSpellData['it'][460474] = {name = "Campo Folgorante", additional_info = "Portata di 100 m\nIstantaneo\n[q]I personaggi nel campo elettrico subiscono il 150% di danni aggiuntivi e subiscono 838509 danni da natura ogni 1 s."}
MultiLanguageSpellData['it'][460475] = {name = "Pirosfera", additional_info = "Portata di 40 m\nIstantaneo\n[q]Scaglia un enorme macigno infuocato, infliggendo ([150% of Spell Power]) danni da fuoco ."}
MultiLanguageSpellData['it'][460476] = {name = "Colonna di Fuoco", additional_info = "Portata di 40 m\n3.5 s di lancio\n[q]Evoca una colonna di fuoco che brucia tutti i nemici nell'area d'effetto, infliggendo ([65% of Spell Power]) danni da fuoco. Danni ridotti oltre 8 bersagli."}
MultiLanguageSpellData['it'][460478] = {name = "Impeto", additional_info = "[q]Permette di suddividersi in 3 spiriti elementali per 15 s, ognuno dei quali infligge o fornisce il 40% dei danni o delle cure normalmente inflitti o forniti.\n\n La Tempesta è sotto tuo controllo diretto, mentre la Terra e il Fuoco imitano gli attacchi sui nemici vicini.\n\n Mentre è attivo, rilanciare Tempesta, Terra e Fuoco fa concentrare tutti gli spiriti elementali sul tuo bersaglio."}
MultiLanguageSpellData['it'][460482] = {name = "Esca per Bestie Suprema", additional_info = "[q0][Item Effect]Portata di 2 m\n{2 s di lancio} {1 min di recupero}\n[q]Piazza l'esca, inducendo una creatura elusiva suprema a uscire dal suo nascondiglio.\n\n Utilizzabile solo nelle Distese Rimbombanti delle Profondità Risonanti."}
