MultiLanguageSpellData['it'][461244] = {name = "Luce Traboccante", additional_info = "[q]Il 30% delle sovracure di Folgore Sacra viene convertito in uno scudo d'assorbimento. I danni subiti assorbiti dallo scudo non possono superare il 10% della salute massima."}
MultiLanguageSpellData['it'][461245] = {name = "Radiosità Splendente", additional_info = "[q]Consumare cariche di potere sacro ha una probabilità del 25% di attivare l'effetto di assorbimento di Salvato dalla Luce al 33% dell'efficacia senza attivarne il tempo di recupero.\n(750ms di recupero)"}
MultiLanguageSpellData['it'][461246] = {name = "Alba Gloriosa", additional_info = "[q]Folgore Sacra ha una probabilità del 12% di ripristinare una carica quando viene lanciata e le cure che fornisce aumentano del 10%."}
MultiLanguageSpellData['it'][461248] = {name = "Alto Voltaggio", additional_info = "[q]I danni inflitti da Missili Arcani hanno una probabilità del 10% di fornire 1 carica arcana.\n\n La probabilità aumenta del 15% ogni volta che Missili Arcani non fornisce alcuna carica arcana."}
MultiLanguageSpellData['it'][461250] = {name = "Luce Solare Crescente", additional_info = "[q][ Crociato Vendicatore : Dopo aver lanciato Crociato Vendicatore, la successiva Folgore Sacra viene lanciata 2 volta aggiuntiva / Dopo aver lanciato Ira Vendicatrice, le successive 2 Folgori Sacre vengono lanciate 2 volta aggiuntiva.]\n Dopo aver lanciato Rintocco Divino, le successive 2 Folgori Sacre vengono lanciate 2 volta aggiuntiva."}
MultiLanguageSpellData['it'][461257] = {name = "Nube Statica", additional_info = "[q]Ogni volta che si lancia Esplosione Arcana, i danni che infligge aumentano del 25%.\n\n Dopo aver raggiunto il 100% di danni bonus, l'effetto si azzera."}
