MultiLanguageSpellData['it'][461264] = {name = "Flusso Fatuo", additional_info = "[q0]Specializzazione de Tank – Riga 1 talento di PvP\n[q]Sostituisce Tocco del Magus\nPortata di 40 m\n{Istantaneo} {15 s di recupero}\n[q]Marchia il bersaglio, aumentandone tutti i danni subiti dal tuo successivo incantesimo diretto del 100%.\n\nFornisce 4 carica arcana."}
MultiLanguageSpellData['it'][461273] = {name = "Verità Imperante", additional_info = "[q]Giudizio ti cura di ([240% of Spell Power]) e il suo costo in mana si riduce del 30%. Il 50% delle sovracure fornite da questo effetto viene trasferito su 2 alleati entro 40 m."}
MultiLanguageSpellData['it'][461278] = {name = "Districamento", additional_info = "[q]Aumenta la probabilità di critico di Parola di Gloria e Luce dell'Alba di massimo il 30%, in base alla salute attuale del bersaglio. Minore la salute, maggiore la probabilità di critico."}
MultiLanguageSpellData['it'][461281] = {name = "Reliquia di Uldum", additional_info = "Portata illimitata\nIstantaneo\n[q]Brann impugna una potente reliquia antica che irradia energia sacra, curando significativamente tutti gli alleati ogni 1 s per 20 s."}
MultiLanguageSpellData['it'][461287] = {name = "Liberazione", additional_info = "Liberazione Livello 80\n[q]Parola di Gloria e Luce dell'Alba hanno una probabilità pari alla tua celerità di ridurre il costo del successivo lancio di Luce Sacra, Lampo di Luce, Assalto del Crociato o Giudizio di 6000 .\n(1s di recupero)"}
MultiLanguageSpellData['it'][461288] = {name = "Bagno di Sangue", additional_info = "Istantaneo\n[q]Attivare Avventatezza genera 50 rabbia. Quando Avventatezza è attiva, Colpo Furente e Sete di Sangue vengono sostituiti da Colpo Devastante e Bagno di Sangue.\n\n Colpo Devastante\nEsegue un attacco brutale con entrambe le armi, infliggendo un totale di [([258.746% of Attack Power]) + ([258.746% of Attack Power])] danni fisici.\n\n Colpo Devastante ha una probabilità del 25% di azzerare istantaneamente il proprio tempo di recupero e infligge il 20% di danni critici aggiuntivi.\n\nGenera 12 rabbia.\n\n Bagno di Sangue\nAssale il bersaglio con una furia sanguinaria, infliggendo ([385.641% of Attack Power]) danni fisici e rigenerando il 3% della salute massima.\n\n Bagno di Sangue fa sanguinare il bersaglio, infliggendo ([60% of Attack Power]) danni aggiuntivi in 6 s. Lanciare Bagno di Sangue su un bersaglio già affetto da Bagno di Sangue estende la durata dell'effetto di sanguinamento di 6 s.\n\nGenera 8 rabbia."}
